import { makeBank } from '../helpers';

/**
 * Ngữ văn 9 (chương trình 2018, thi vào 10 Hà Nội) — ngân hàng câu hỏi mức 3–5.
 * Chỉ trích văn bản đã hết bản quyền (ca dao, tục ngữ, thơ trung đại) và các đoạn văn tự viết;
 * với tác giả hiện đại chỉ nêu tên tác giả, tác phẩm như dữ kiện, không trích dẫn.
 * choices[0] là đáp án đúng (ứng dụng sẽ trộn). Lời giải thích dạy quy tắc và chỉ ra bẫy.
 */
const { add, list } = makeBank('Atlas grade 9 bank', 'g9b-');
const ex = (explanation: string) => ({ explanation });

// ── Đọc hiểu văn bản ─────────────────────────────────────────
const CO = 'lit.comprehension';

const DOC_CHAM = `Chúng ta đang sống trong thời đại của những cú chạm màn hình. Mỗi ngày, một học sinh có thể lướt qua hàng trăm đoạn video ngắn, nhưng hiếm khi đọc trọn một cuốn sách. Lướt nhanh giúp ta biết nhiều thứ, nhưng chỉ biết trên bề mặt. Đọc chậm thì khác: nó buộc ta dừng lại, đặt câu hỏi, tưởng tượng và tự rút ra ý nghĩa.

Có lẽ ai cũng từng gặp một cuốn sách khiến mình nhớ mãi. Một trang sách được đọc kĩ có thể ở lại với ta nhiều năm, còn một trăm đoạn video lướt qua thường biến mất ngay khi màn hình tắt.

Đọc chậm không có nghĩa là quay lưng với công nghệ. Ta vẫn có thể đọc sách điện tử, nghe sách nói. Điều quan trọng là dành cho mình những khoảng lặng để nghĩ cho sâu.
(Đoạn văn tự viết)`;
const dc = { passage: DOC_CHAM, setId: 'lit-g9b-doc-cham' };
add(CO, 3, 'Phương thức biểu đạt chính của văn bản là gì?', ['Nghị luận', 'Tự sự', 'Biểu cảm', 'Thuyết minh'], { ...dc, ...ex('Văn bản nêu một ý kiến (nên đọc chậm, đọc sâu) và dùng lí lẽ để thuyết phục → nghị luận. Bẫy "tự sự": có nhắc tới việc học sinh lướt video nhưng đó chỉ là dẫn chứng, không có nhân vật hay cốt truyện.') });
add(CO, 3, 'Vấn đề chính được bàn luận trong văn bản là…', ['giá trị của việc đọc chậm, đọc sâu trong thời đại lướt nhanh', 'tác hại của điện thoại thông minh đối với sức khoẻ', 'cách làm video ngắn thu hút người xem', 'ưu điểm của sách điện tử so với sách giấy'], { ...dc, ...ex('Muốn tìm vấn đề, hãy hỏi: câu nào cả ba đoạn cùng hướng tới? Cả ba đoạn đều xoay quanh "đọc chậm". Điện thoại và sách điện tử chỉ là chi tiết phụ, chọn chúng là lấy một phần thay cho toàn bộ.') });
add(CO, 4, 'Ở đoạn 1, tác giả chủ yếu dùng thao tác lập luận nào?', ['So sánh (đối chiếu "lướt nhanh" với "đọc chậm")', 'Chứng minh bằng số liệu thống kê', 'Bác bỏ một ý kiến sai', 'Kể chuyện để rút ra bài học'], { ...dc, ...ex('Dấu hiệu so sánh: đặt hai đối tượng cạnh nhau, có từ chỉ sự khác biệt ("nhưng", "thì khác"). Bẫy "chứng minh bằng số liệu": "hàng trăm đoạn video" là cách nói ước chừng, không phải số liệu khảo sát.') });
add(CO, 4, 'Đoạn 3 ("Đọc chậm không có nghĩa là quay lưng với công nghệ…") có vai trò gì?', ['Lường trước và gạt bỏ một cách hiểu sai, làm lập luận chặt chẽ hơn', 'Kể thêm một câu chuyện để minh hoạ', 'Phủ nhận toàn bộ ý kiến ở đoạn 1', 'Giới thiệu một vấn đề hoàn toàn mới'], { ...dc, ...ex('Người viết đoán người đọc có thể hiểu lầm "đọc chậm = chống công nghệ" nên chủ động gạt đi. Đây là cách xử lí phản đề. Đoạn 3 không phủ nhận đoạn 1 mà làm rõ thêm cho nó.') });
add(CO, 5, 'Câu nào nêu rõ nhất quan điểm của người viết?', ['Điều quan trọng là dành cho mình những khoảng lặng để nghĩ cho sâu.', 'Chúng ta đang sống trong thời đại của những cú chạm màn hình.', 'Ta vẫn có thể đọc sách điện tử, nghe sách nói.', 'Có lẽ ai cũng từng gặp một cuốn sách khiến mình nhớ mãi.'], { ...dc, ...ex('Câu nêu quan điểm thường mang tính đánh giá hoặc đề xuất ("điều quan trọng là…", "cần…"). Câu mở đầu chỉ dẫn dắt vào vấn đề, còn câu về sách điện tử chỉ là ý phụ.') });
add(CO, 5, 'Thông điệp phù hợp nhất rút ra từ văn bản là…', ['Giữa dòng thông tin nhanh, hãy giữ cho mình thói quen đọc chậm và suy nghĩ sâu.', 'Hãy bỏ hẳn điện thoại để chỉ đọc sách giấy.', 'Đọc càng nhiều sách thì càng giỏi.', 'Video ngắn hoàn toàn vô ích.'], { ...dc, ...ex('Thông điệp phải đúng với tinh thần văn bản và không cực đoan. Văn bản đã nói rõ "không quay lưng với công nghệ", nên các phương án "bỏ hẳn", "hoàn toàn vô ích" đều nói quá ý tác giả. Đề thi rất hay đặt bẫy kiểu này.') });

const CAY_BANG = `Cây bàng ở góc sân trường đã đứng đó lâu hơn tuổi của cả lớp tôi cộng lại. Mùa đông, nó trút hết lá, giơ những cành khẳng khiu lên trời, lặng lẽ chờ đợi. Rồi một sáng tháng Ba, chúng tôi ngẩn người khi thấy cả tán cây lấm tấm chồi non xanh biếc, như ai vừa thắp lên hàng nghìn ngọn nến nhỏ.

Năm nay là năm cuối cấp. Tôi biết mùa hè tới, khi những chùm quả bàng chín vàng, chúng tôi sẽ không còn ngồi dưới gốc cây này nữa. Cây bàng vẫn sẽ ở lại, vẫn trút lá rồi nảy lộc, chỉ có chúng tôi là phải lớn lên và đi xa.
(Đoạn văn tự viết)`;
const cb = { passage: CAY_BANG, setId: 'lit-g9b-cay-bang' };
add(CO, 3, 'Phương thức biểu đạt chính của đoạn văn là…', ['Biểu cảm', 'Miêu tả', 'Nghị luận', 'Thuyết minh'], { ...cb, ...ex('Đoạn văn có miêu tả cây bàng, nhưng miêu tả để bộc lộ cảm xúc lưu luyến của "tôi" → biểu cảm là chính. Mẹo: nếu đoạn văn kết lại bằng cảm xúc, suy tư của người viết thì phương thức chính là biểu cảm; miêu tả chỉ hỗ trợ.') });
add(CO, 3, 'Hình ảnh "như ai vừa thắp lên hàng nghìn ngọn nến nhỏ" gợi điều gì về những chồi non?', ['Chồi non bừng sáng, tràn đầy sức sống như ánh lửa nhỏ', 'Cây bàng sắp bị cháy', 'Chồi non rất ít và yếu ớt', 'Trời tháng Ba rất nóng'], { ...cb, ...ex('Đây là phép so sánh (có "như"). Ngọn nến gợi ánh sáng, sự ấm áp, sự sống được "thắp lên". Đừng hiểu hình ảnh so sánh theo nghĩa đen (cây bị cháy).') });
add(CO, 4, 'Chi tiết "chúng tôi ngẩn người" thể hiện điều gì?', ['Sự ngạc nhiên, xúc động trước sự hồi sinh của cây bàng', 'Các bạn đang buồn ngủ', 'Các bạn sợ hãi cây bàng', 'Các bạn không để ý đến cây bàng'], { ...cb, ...ex('"Ngẩn người" là trạng thái sững lại vì bất ngờ. Đặt cạnh hình ảnh cây trụi lá mùa đông rồi bỗng đầy chồi non, ta thấy đó là sự ngạc nhiên, thích thú trước sức sống mới.') });
add(CO, 4, 'Câu cuối đặt cây bàng và "chúng tôi" trong thế đối lập nào?', ['Cây bàng ở lại và tuần hoàn mãi; con người phải lớn lên và rời đi', 'Cây bàng già yếu; con người khoẻ mạnh', 'Cây bàng vui; con người buồn', 'Cây bàng thay đổi; con người đứng yên'], { ...cb, ...ex('Cây "vẫn trút lá rồi nảy lộc" (vòng tuần hoàn lặp lại), còn "chúng tôi" thì "lớn lên và đi xa" (một chiều, không quay lại). Phép đối lập này làm nổi bật nỗi bâng khuâng khi tuổi học trò trôi qua.') });
add(CO, 5, 'Chủ đề của đoạn văn là…', ['Tình gắn bó với mái trường và nỗi bâng khuâng khi tuổi học trò sắp khép lại', 'Cách chăm sóc cây bàng trong sân trường', 'Đặc điểm sinh học của cây bàng qua bốn mùa', 'Niềm vui được nghỉ hè'], { ...cb, ...ex('Cây bàng là hình ảnh trung tâm nhưng chủ đề là cảm xúc của con người gửi qua hình ảnh ấy. Bẫy "đặc điểm cây bàng": nhầm đối tượng miêu tả với vấn đề tác giả muốn nói.') });

const NGUNG_BICH = `Buồn trông cửa bể chiều hôm,
Thuyền ai thấp thoáng cánh buồm xa xa?
Buồn trông ngọn nước mới sa,
Hoa trôi man mác biết là về đâu?
Buồn trông nội cỏ rầu rầu,
Chân mây mặt đất một màu xanh xanh.
Buồn trông gió cuốn mặt duềnh,
Ầm ầm tiếng sóng kêu quanh ghế ngồi.
(Nguyễn Du, Truyện Kiều — đoạn Kiều ở lầu Ngưng Bích)`;
const nb = { passage: NGUNG_BICH, setId: 'lit-g9b-ngung-bich' };
add(CO, 3, 'Cụm từ "Buồn trông" được lặp lại bốn lần là biện pháp gì?', ['Điệp ngữ', 'Liệt kê', 'Hoán dụ', 'Nói quá'], { ...nb, ...ex('Lặp lại cùng một cụm từ ở đầu các câu là điệp ngữ (điệp ngữ cách quãng). Nó tạo nhịp điệu như những đợt sóng lòng, nhấn mạnh nỗi buồn triền miên của Kiều. Liệt kê là kể ra nhiều sự vật cùng loại, không phải lặp một từ.') });
add(CO, 3, 'Đoạn thơ sử dụng bút pháp nghệ thuật đặc trưng nào?', ['Tả cảnh ngụ tình', 'Tả cảnh thuần tuý', 'Kể chuyện theo trình tự thời gian', 'Miêu tả ngoại hình nhân vật'], { ...nb, ...ex('Mỗi cảnh (cửa bể, hoa trôi, nội cỏ, sóng) đều nhuốm tâm trạng của Kiều: cô đơn, lo âu. Mượn cảnh để nói tình là tả cảnh ngụ tình. Nhớ câu: "Người buồn cảnh có vui đâu bao giờ" (cũng của Nguyễn Du).') });
add(CO, 4, 'Hình ảnh "Hoa trôi man mác biết là về đâu?" gợi điều gì về Kiều?', ['Thân phận trôi nổi, không biết sẽ dạt về đâu', 'Kiều thích ngắm hoa', 'Mùa xuân đã đến', 'Kiều sắp được đoàn tụ với gia đình'], { ...nb, ...ex('Cánh hoa (thường ẩn dụ cho người con gái) trôi theo dòng nước, không tự quyết được hướng đi, giống thân phận Kiều lúc này. Câu hỏi tu từ "biết là về đâu?" bộc lộ nỗi hoang mang về tương lai.') });
add(CO, 4, 'Các câu hỏi "Thuyền ai…?", "…biết là về đâu?" là loại câu gì?', ['Câu hỏi tu từ, dùng để bộc lộ cảm xúc chứ không cần trả lời', 'Câu hỏi thật, Kiều muốn người khác trả lời', 'Câu cầu khiến', 'Câu trần thuật'], { ...nb, ...ex('Kiều ở một mình, không hỏi ai cả. Câu hỏi không chờ câu trả lời mà để bày tỏ nỗi lòng là câu hỏi tu từ.') });
add(CO, 5, 'Trình tự cảnh vật trong tám câu thơ thể hiện tâm trạng Kiều như thế nào?', ['Cảnh đi từ xa đến gần, màu từ nhạt đến đậm, âm thanh từ tĩnh đến dữ dội: nỗi buồn và lo sợ tăng dần', 'Cảnh đi từ buồn đến vui: Kiều dần nguôi ngoai', 'Cảnh không theo trình tự nào', 'Cảnh đi từ gần ra xa: Kiều dần quên quá khứ'], { ...nb, ...ex('Thuyền "xa xa" → hoa trôi → nội cỏ → sóng "kêu quanh ghế ngồi" (ngay sát bên); âm thanh từ im lặng đến "ầm ầm". Cảnh càng lúc càng dồn dập, ứng với tâm trạng càng lúc càng hoảng sợ. Đây là ý phân tích hay nhất của đoạn trích.') });
add(CO, 5, 'Hai câu cuối ("Buồn trông gió cuốn mặt duềnh, / Ầm ầm tiếng sóng kêu quanh ghế ngồi") dự báo điều gì?', ['Những tai hoạ, sóng gió sắp ập đến cuộc đời Kiều', 'Một cơn bão thật sắp đổ bộ', 'Kiều sắp được cứu thoát', 'Mùa xuân trở lại'], { ...nb, ...ex('Trong tả cảnh ngụ tình, sóng gió của thiên nhiên thường là dự cảm về sóng gió cuộc đời. Ngay sau đoạn này, Kiều rơi vào bẫy của Sở Khanh và tiếp tục lưu lạc. Đừng đọc theo nghĩa đen "cơn bão thật".') });

// ── Biện pháp tu từ ───────────────────────────────────────────
const DV = 'lit.devices';
add(DV, 3, '"Cày đồng đang buổi ban trưa, / Mồ hôi thánh thót như mưa ruộng cày." (Ca dao) — biện pháp tu từ chính trong câu 2 là…', ['So sánh', 'Nhân hoá', 'Hoán dụ', 'Điệp ngữ'], ex('Có từ so sánh "như": mồ hôi được ví với mưa. Hình ảnh nhấn mạnh sự vất vả của người nông dân. Nhận ra so sánh bằng các từ: như, là, tựa, bao nhiêu… bấy nhiêu.'));
add(DV, 3, '"Thân em như tấm lụa đào, / Phất phơ giữa chợ biết vào tay ai." (Ca dao) — phép so sánh gợi điều gì?', ['Người phụ nữ đẹp, quý giá nhưng số phận bấp bênh, không tự quyết định được', 'Người phụ nữ giàu có, buôn bán lụa', 'Người phụ nữ yếu đuối, lười biếng', 'Chợ quê rất đông vui'], ex('"Lụa đào" đẹp và quý; "phất phơ giữa chợ" thì trôi nổi, chờ người mua. Mô típ "Thân em như…" trong ca dao than thân luôn nói về thân phận phụ thuộc của người phụ nữ xưa.'));
add(DV, 4, '"Hoa ghen thua thắm liễu hờn kém xanh" (Nguyễn Du) — biện pháp nghệ thuật nổi bật là…', ['Nhân hoá', 'So sánh có từ "như"', 'Hoán dụ', 'Nói giảm nói tránh'], ex('"Ghen", "hờn" là cảm xúc của con người được gán cho hoa và liễu → nhân hoá. Vẻ đẹp của Kiều khiến thiên nhiên phải ghen ghét, dự báo một số phận nhiều sóng gió.'));
add(DV, 4, '"Bầu ơi thương lấy bí cùng, / Tuy rằng khác giống nhưng chung một giàn." (Ca dao) — "bầu" và "bí" là hình ảnh ẩn dụ cho…', ['những con người khác nhau nhưng cùng chung một đất nước', 'hai loại rau trong vườn', 'hai anh em ruột', 'người giàu và người nghèo'], ex('Ẩn dụ dựa trên sự giống nhau: bầu và bí khác giống nhưng chung giàn, như người khác quê, khác hoàn cảnh nhưng chung một nước. Đây cũng là nhân hoá (gọi "bầu ơi" như gọi người).'));
add(DV, 3, '"Cả làng thức dậy, đổ ra đầu ngõ đón đoàn quân trở về." Từ "làng" là biện pháp…', ['Hoán dụ (lấy nơi chốn để chỉ người sống ở đó)', 'Ẩn dụ', 'Nhân hoá', 'So sánh'], ex('Hoán dụ dựa trên quan hệ gần gũi (vật chứa – vật bị chứa): "làng" chỉ người dân trong làng. Bẫy "nhân hoá": "làng thức dậy" nghe như nhân hoá, nhưng thực ra người thức dậy là dân làng, nên đây là hoán dụ.'));
add(DV, 4, 'Điểm khác nhau cốt lõi giữa ẩn dụ và hoán dụ là gì?', ['Ẩn dụ dựa trên quan hệ giống nhau; hoán dụ dựa trên quan hệ gần gũi, liên quan', 'Ẩn dụ có từ "như"; hoán dụ không có', 'Ẩn dụ chỉ dùng trong thơ; hoán dụ chỉ dùng trong văn xuôi', 'Ẩn dụ dùng cho người; hoán dụ dùng cho vật'], ex('Mẹo kiểm tra: nếu thay được bằng "A giống B" → ẩn dụ (thuyền – người con trai đi xa). Nếu A là một bộ phận, dấu hiệu, nơi chốn… của B → hoán dụ (áo chàm – người Việt Bắc). Từ "như" là dấu hiệu của so sánh, không phải ẩn dụ.'));
add(DV, 4, '"Lom khom dưới núi, tiều vài chú, / Lác đác bên sông, chợ mấy nhà." (Bà Huyện Thanh Quan) — biện pháp nổi bật là…', ['Đảo ngữ (đưa từ láy lên đầu câu) kết hợp phép đối', 'So sánh', 'Nhân hoá', 'Nói quá'], ex('Trật tự thông thường là "vài chú tiều lom khom dưới núi". Đưa "lom khom", "lác đác" lên đầu câu (đảo ngữ) nhấn mạnh sự nhỏ bé, thưa thớt. Hai câu còn đối nhau từng vế (lom khom – lác đác, dưới núi – bên sông), tô đậm cảnh vắng vẻ.'));
add(DV, 5, '"Nhớ nước đau lòng con quốc quốc, / Thương nhà mỏi miệng cái gia gia." (Bà Huyện Thanh Quan) — ngoài phép đối, hai câu thơ còn dùng biện pháp nào?', ['Chơi chữ (đồng âm): "quốc" là nước, "gia" là nhà', 'Hoán dụ', 'Nói giảm nói tránh', 'Liệt kê'], ex('"Quốc quốc" là tiếng chim cuốc, "gia gia" là tiếng chim đa đa, nhưng "quốc" (nước) và "gia" (nhà) trong Hán Việt lại trùng với "nhớ nước", "thương nhà". Lợi dụng hiện tượng đồng âm như vậy là chơi chữ.'));
add(DV, 3, '"Ông cụ đã yên nghỉ sau một đời vất vả." Cách nói "yên nghỉ" là…', ['Nói giảm nói tránh', 'Nói quá', 'Ẩn dụ', 'Liệt kê'], ex('Dùng cách nói nhẹ nhàng ("yên nghỉ", "đi xa", "về với tổ tiên") thay cho "chết" để tránh gây đau buồn, thể hiện sự tôn trọng → nói giảm nói tránh. Nói quá thì ngược lại: phóng đại.'));
add(DV, 3, '"Bài kiểm tra khó đến mức cả lớp nghĩ nát óc mà không ra." Cụm "nghĩ nát óc" là…', ['Nói quá', 'Nói giảm nói tránh', 'Hoán dụ', 'So sánh'], ex('Phóng đại mức độ (không ai nghĩ đến "nát óc" thật) để nhấn mạnh → nói quá. Nói quá khác nói khoác: nói quá nhằm nhấn mạnh, gây ấn tượng; nói khoác nhằm khoe khoang, lừa người nghe.'));
add(DV, 4, '"Tôi nhớ con đường đất đỏ, nhớ hàng phượng già, nhớ cả tiếng trống trường mỗi sớm." Câu văn dùng những biện pháp nào?', ['Điệp ngữ ("nhớ") và liệt kê', 'Chỉ có so sánh', 'Nhân hoá và hoán dụ', 'Nói quá và nói giảm'], ex('Từ "nhớ" được lặp lại ba lần → điệp ngữ. Con đường, hàng phượng, tiếng trống được kể nối tiếp nhau → liệt kê. Một câu có thể dùng nhiều biện pháp; đề hay hỏi "những biện pháp nào" để kiểm tra điều này.'));
add(DV, 4, '"Gần mực thì đen, gần đèn thì rạng." (Tục ngữ) — câu tục ngữ được xây dựng chủ yếu bằng…', ['Phép đối (mực – đèn, đen – rạng) kết hợp ẩn dụ', 'Phép so sánh có từ "như"', 'Phép nói giảm', 'Phép liệt kê'], ex('Hai vế cân xứng, ý trái ngược: mực/đèn, đen/rạng → phép đối. "Mực" ẩn dụ cho người xấu, môi trường xấu; "đèn" cho người tốt. Ý nghĩa: môi trường sống ảnh hưởng lớn tới con người.'));
add(DV, 5, '"Nắng giòn tan trên mái ngói." Từ "giòn tan" thể hiện kiểu ẩn dụ nào?', ['Ẩn dụ chuyển đổi cảm giác', 'Ẩn dụ hình thức', 'Hoán dụ bộ phận – toàn thể', 'Nhân hoá'], ex('"Giòn tan" vốn thuộc vị giác/xúc giác (bánh giòn), lại dùng để tả nắng (thị giác). Dùng từ của giác quan này để tả cảm nhận của giác quan khác là ẩn dụ chuyển đổi cảm giác. Nó làm cảm nhận trở nên mới lạ, sống động.'));
add(DV, 5, '"Thuyền ai thấp thoáng cánh buồm xa xa?" (Nguyễn Du) — câu thơ có dạng câu hỏi nhưng chủ yếu để…', ['bộc lộ nỗi cô đơn, mong ngóng (câu hỏi tu từ)', 'hỏi tên người lái thuyền', 'ra lệnh cho thuyền quay lại', 'thông báo có thuyền đến'], ex('Câu hỏi tu từ không cần trả lời, dùng để bộc lộ cảm xúc hoặc khẳng định một điều. Kiều một mình ở lầu Ngưng Bích, nhìn cánh buồm xa mà nhớ nhà, không thật sự hỏi ai.'));
add(DV, 4, 'Khi trả lời câu hỏi "Nêu tác dụng của biện pháp tu từ", cách trả lời đầy đủ nhất là…', ['Gọi tên biện pháp, chỉ ra từ ngữ; nêu tác dụng tạo hình ảnh, nhấn mạnh nội dung gì và thể hiện tình cảm gì của tác giả', 'Chỉ cần gọi tên biện pháp', 'Chỉ cần viết "làm câu văn hay hơn"', 'Chép lại câu thơ'], ex('Đáp án chấm thường có 3 ý: (1) gọi tên + chỉ từ ngữ; (2) tác dụng nghệ thuật: sinh động, gợi hình, gợi cảm; (3) tác dụng nội dung: nhấn mạnh điều gì, bộc lộ cảm xúc gì. Viết chung chung "làm câu văn hay hơn" sẽ mất điểm.'));
add(DV, 5, '"Một cây làm chẳng nên non, / Ba cây chụm lại nên hòn núi cao." (Ca dao) — "một cây" và "ba cây" là ẩn dụ cho…', ['sức mạnh lẻ loi của một người và sức mạnh của sự đoàn kết', 'nghề trồng cây gây rừng', 'số lượng cây trên núi', 'người già và người trẻ'], ex('Ẩn dụ dựa trên sự giống nhau: một cây không làm nên núi như một người không làm nên việc lớn; nhiều cây chụm lại như nhiều người đoàn kết. Hiểu nghĩa đen "trồng cây" là bỏ qua tầng nghĩa ẩn dụ của ca dao.'));
add(DV, 3, '"Gió đùa nghịch với những tàu lá chuối, khiến chúng vẫy tay rối rít." Câu văn sử dụng biện pháp…', ['Nhân hoá', 'Hoán dụ', 'Nói quá', 'Điệp ngữ'], ex('"Đùa nghịch", "vẫy tay" là hoạt động của con người gán cho gió và lá chuối → nhân hoá. Nhân hoá có 3 kiểu: gọi vật bằng từ gọi người; tả vật bằng từ tả người; trò chuyện với vật như với người.'));

// ── Phân tích lập luận ────────────────────────────────────────
const AR = 'lit.argument';
const LAP_LUAN = `(1) Tình nguyện không phải là việc chỉ dành cho người lớn. (2) Một học sinh lớp 9 hoàn toàn có thể góp sức cho cộng đồng bằng những việc vừa sức: dọn rác ở bãi biển, dạy kèm em nhỏ, quyên góp sách cũ. (3) Năm ngoái, câu lạc bộ của trường tôi đã gửi hơn 600 cuốn sách lên một điểm trường vùng cao. (4) Những việc ấy không chỉ giúp người khác mà còn giúp chính chúng ta trưởng thành, biết sẻ chia và sống có trách nhiệm.
(Đoạn văn tự viết)`;
const ll = { passage: LAP_LUAN, setId: 'lit-g9b-tinh-nguyen' };
add(AR, 3, 'Câu nào nêu luận điểm của đoạn văn?', ['Câu (1)', 'Câu (2)', 'Câu (3)', 'Câu (4)'], { ...ll, ...ex('Luận điểm là ý kiến chính, các câu khác đều phục vụ nó. Câu (1) khẳng định "tình nguyện không chỉ dành cho người lớn"; câu (2) giải thích, câu (3) là bằng chứng, câu (4) nêu ý nghĩa.') });
add(AR, 3, 'Câu (3) đóng vai trò gì trong lập luận?', ['Bằng chứng (sự việc, số liệu cụ thể)', 'Luận điểm', 'Lí lẽ', 'Phản đề'], { ...ll, ...ex('Bằng chứng là sự việc, số liệu, nhân vật có thật, kiểm chứng được: "hơn 600 cuốn sách". Lí lẽ thì là những lời giải thích, phân tích, như câu (2) và (4).') });
add(AR, 4, 'Câu (4) chủ yếu là…', ['Lí lẽ, chỉ ra ý nghĩa của việc tình nguyện', 'Bằng chứng', 'Phản đề', 'Câu chuyển đoạn'], { ...ll, ...ex('Câu (4) không đưa sự việc cụ thể mà giải thích vì sao việc tình nguyện có giá trị → lí lẽ. Mẹo: nếu câu trả lời câu hỏi "vì sao/như thế nào" thì là lí lẽ; nếu trả lời "ví dụ nào/bao nhiêu" thì là bằng chứng.') });
add(AR, 4, 'Thông tin nào là ý kiến chủ quan, không phải sự thật khách quan?', ['Đọc sách giấy thú vị hơn đọc sách điện tử.', 'Truyện Kiều có 3254 câu thơ.', 'Hồ Gươm nằm ở trung tâm Hà Nội.', 'Năm 2024 có 366 ngày.'], ex('Sự thật khách quan có thể kiểm chứng đúng/sai bằng số liệu, tài liệu. Ý kiến chủ quan là đánh giá, sở thích, thường có từ như "thú vị hơn, nên, tốt nhất…" — người khác có thể không đồng ý. Phân biệt hai loại này là yêu cầu của chương trình mới.'));
add(AR, 4, '"Hôm qua tôi ăn kem rồi bị điểm kém. Vậy ăn kem làm học kém." Lập luận này mắc lỗi gì?', ['Suy luận nhân quả sai: hai việc xảy ra liền nhau chưa chắc là nguyên nhân – kết quả', 'Thiếu luận điểm', 'Dùng quá nhiều bằng chứng', 'Lạc đề'], ex('Việc B xảy ra sau việc A không có nghĩa A gây ra B. Muốn kết luận nhân quả cần chỉ ra mối liên hệ hợp lí. Lỗi này rất hay gặp trong tranh luận đời thường.'));
add(AR, 5, '"Bạn tôi chơi game rồi học kém, anh họ tôi cũng thế. Vậy ai chơi game cũng học kém." Lập luận mắc lỗi…', ['Khái quát vội vàng từ quá ít trường hợp', 'Đánh tráo khái niệm', 'Công kích cá nhân', 'Không có kết luận'], ex('Chỉ hai ví dụ không đủ để kết luận cho "tất cả mọi người". Bằng chứng phải đủ, tiêu biểu thì kết luận mới đáng tin. Nhận biết: kết luận có từ "ai cũng, tất cả, mọi" nhưng dẫn chứng thì ít ỏi.'));
add(AR, 5, 'A nói: "Nên giảm bài tập về nhà." B đáp: "Cậu lười thì mới nói vậy." Câu trả lời của B mắc lỗi gì?', ['Công kích cá nhân thay vì phản bác ý kiến', 'Khái quát vội vàng', 'Đưa số liệu sai', 'Lập luận quá chặt chẽ'], ex('B không chứng minh vì sao ý kiến của A sai mà quay sang chê con người A. Muốn bác bỏ phải chỉ ra chỗ sai của luận điểm, lí lẽ hoặc bằng chứng, không đánh vào người nói.'));
add(AR, 3, 'Mục đích chính của văn nghị luận là gì?', ['Thuyết phục người đọc đồng tình với một ý kiến, quan điểm', 'Kể lại một câu chuyện hấp dẫn', 'Bộc lộ cảm xúc cá nhân', 'Cung cấp thông tin khách quan về một sự vật'], ex('Nghị luận = bàn bạc để thuyết phục, dùng luận điểm, lí lẽ, bằng chứng. Cung cấp thông tin khách quan là mục đích của văn bản thông tin; bộc lộ cảm xúc là biểu cảm.'));
add(AR, 3, 'Trong văn nghị luận, "luận đề" khác "luận điểm" ở chỗ…', ['Luận đề là vấn đề bao trùm cả bài; luận điểm là các ý kiến cụ thể triển khai luận đề', 'Luận đề là dẫn chứng; luận điểm là lí lẽ', 'Luận đề nằm ở kết bài; luận điểm nằm ở mở bài', 'Hai khái niệm hoàn toàn giống nhau'], ex('Một bài có một luận đề (vấn đề chung) và nhiều luận điểm (ý lớn), mỗi luận điểm lại được làm rõ bằng lí lẽ và bằng chứng. Hình dung như cái cây: luận đề là gốc, luận điểm là cành.'));
add(AR, 4, '"Trung thực là nói đúng sự thật, hành động đúng với suy nghĩ, không gian dối với người khác và với chính mình." Câu văn thực hiện thao tác lập luận nào?', ['Giải thích', 'Chứng minh', 'Bác bỏ', 'So sánh'], ex('Câu trả lời cho câu hỏi "trung thực là gì?" → giải thích. Chứng minh thì phải đưa ra bằng chứng thực tế (người thật, việc thật).'));
add(AR, 4, 'Ý kiến: "Học giỏi thì không cần rèn kĩ năng sống." Cách bác bỏ thuyết phục nhất là…', ['Chỉ ra những trường hợp học giỏi nhưng thiếu kĩ năng nên gặp khó khăn, và phân tích vì sao kiến thức cần đi cùng kĩ năng', 'Nói rằng người nêu ý kiến không hiểu gì', 'Nhắc lại ý kiến đó nhiều lần', 'Đồng ý một nửa cho xong'], ex('Bác bỏ hiệu quả = chỉ ra chỗ sai bằng lí lẽ và bằng chứng, rồi nêu quan điểm đúng. Chê người nói là công kích cá nhân, không có giá trị thuyết phục.'));
add(AR, 4, 'Bằng chứng nào phù hợp nhất cho luận điểm "Kiên trì giúp con người vượt qua thất bại"?', ['Thomas Edison đã thử nghiệm hàng nghìn lần trước khi làm ra bóng đèn dùng được lâu.', 'Edison là người Mỹ.', 'Bóng đèn ngày nay rất rẻ.', 'Có nhiều loại bóng đèn khác nhau.'], ex('Bằng chứng phải liên quan trực tiếp tới luận điểm. Chỉ câu về những lần thử nghiệm mới cho thấy kiên trì dẫn tới thành công; các câu còn lại đều đúng sự thật nhưng không chứng minh được gì.'));
add(AR, 5, '"Hoặc là em học chuyên Toán, hoặc là em chẳng có tương lai." Lập luận này mắc lỗi gì?', ['Đưa ra lựa chọn sai: chỉ đặt hai khả năng cực đoan trong khi còn nhiều khả năng khác', 'Dùng bằng chứng quá cụ thể', 'Khái quát từ số liệu', 'Thiếu từ nối'], ex('Lỗi "chỉ có hai lựa chọn" (trắng hoặc đen) bỏ qua những khả năng ở giữa. Nhận biết qua cấu trúc "hoặc là… hoặc là…" mang tính đe doạ hoặc tuyệt đối.'));
add(AR, 3, 'Thao tác "phân tích" trong văn nghị luận là…', ['chia vấn đề thành các khía cạnh nhỏ để xem xét kĩ từng mặt', 'kể lại một câu chuyện có thật', 'đưa ra số liệu thống kê', 'nhắc lại luận điểm ở kết bài'], ex('Phân tích = chia nhỏ để hiểu sâu (nguyên nhân, biểu hiện, tác hại…). Đưa số liệu là cách chứng minh; còn nhắc lại luận điểm là việc của kết bài.'));
add(AR, 5, 'Vì sao một bài nghị luận tốt nên nêu và phản bác ý kiến trái chiều?', ['Để cho thấy người viết đã xem xét vấn đề nhiều mặt, khiến luận điểm chặt chẽ và đáng tin hơn', 'Để bài viết dài hơn', 'Để thay đổi quan điểm giữa chừng', 'Vì đề bài luôn bắt buộc phải có'], ex('Khi lường trước và giải đáp được phản biện, người viết cho thấy lập luận của mình đã "chịu được thử thách". Mục đích không phải kéo dài bài hay đổi ý.'));
add(AR, 4, 'Câu nào là lí lẽ (không phải bằng chứng) cho luận điểm "Cần tiết kiệm nước"?', ['Nước sạch không phải vô tận, dùng lãng phí hôm nay là lấy đi nguồn nước của ngày mai.', 'Theo một báo cáo, nhiều vùng từng bị thiếu nước sinh hoạt vào mùa khô.', 'Gia đình tôi giảm được một phần ba hoá đơn tiền nước sau khi sửa vòi rò rỉ.', 'Năm ngoái, trường tôi lắp bể thu nước mưa để tưới cây.'], ex('Lí lẽ là lập luận chung, giải thích vì sao. Ba phương án còn lại đều là sự việc cụ thể (báo cáo, gia đình tôi, trường tôi) → bằng chứng.'));

// ── Cấu trúc bài viết ────────────────────────────────────────
const ST = 'lit.structure';
add(ST, 3, 'Đoạn văn sau thuộc kiểu nào? "Sáng nào mẹ cũng dậy từ năm giờ để nấu cơm. Chiều về, mẹ lại tất tả đi chợ, giặt giũ. Tối đến, mẹ còn ngồi kèm em học bài. Mẹ là người vất vả nhất nhà tôi."', ['Quy nạp', 'Diễn dịch', 'Song song', 'Tổng – phân – hợp'], ex('Các câu đầu nêu những việc cụ thể, câu cuối mới khái quát ý chính ("Mẹ là người vất vả nhất") → câu chủ đề ở cuối → quy nạp. Nếu câu ấy đứng đầu thì đoạn sẽ là diễn dịch.'));
add(ST, 3, 'Đoạn văn có câu chủ đề ở đầu, các câu giữa triển khai, câu cuối khái quát nâng cao ý thì gọi là đoạn…', ['Tổng – phân – hợp', 'Quy nạp', 'Song song', 'Móc xích'], ex('Tổng (câu đầu nêu ý chung) – phân (các câu triển khai) – hợp (câu cuối khẳng định, nâng ý). Khác với diễn dịch ở chỗ có thêm câu kết khái quát ở cuối.'));
add(ST, 3, '"Hà Nội có Hồ Gươm xanh biếc. Hà Nội có phố cổ với những mái ngói rêu phong. Hà Nội còn có những hàng sấu già rợp bóng." Các câu ngang hàng, không có câu chủ đề. Đây là đoạn…', ['Song song (song hành)', 'Diễn dịch', 'Quy nạp', 'Tổng – phân – hợp'], ex('Trong đoạn song song, mỗi câu nêu một khía cạnh, các câu bình đẳng với nhau, không câu nào bao quát các câu còn lại. Thử bỏ một câu bất kì: các câu kia vẫn đứng vững → song song.'));
add(ST, 4, 'Một câu chủ đề tốt cần có đặc điểm gì?', ['Ngắn gọn, khái quát, nêu được ý chính của cả đoạn', 'Thật dài và chứa nhiều dẫn chứng', 'Luôn là câu hỏi', 'Luôn bắt đầu bằng "Tóm lại"'], ex('Câu chủ đề như "tấm biển chỉ đường" của đoạn: đọc nó là biết đoạn nói gì. Dẫn chứng thuộc về các câu triển khai, không nhồi vào câu chủ đề.'));
add(ST, 4, 'Mở bài gián tiếp khác mở bài trực tiếp ở chỗ…', ['Dẫn dắt từ một ý liên quan (câu thơ, câu chuyện, nhận định) rồi mới nêu vấn đề', 'Không cần nêu vấn đề', 'Viết dài hơn thân bài', 'Chỉ dùng cho văn tự sự'], ex('Mở bài trực tiếp: nêu ngay vấn đề. Mở bài gián tiếp: dẫn dắt rồi mới vào vấn đề. Dù trực tiếp hay gián tiếp, mở bài bắt buộc phải nêu được vấn đề cần bàn.'));
add(ST, 4, 'Nhiệm vụ của kết bài trong bài nghị luận là…', ['Khẳng định lại vấn đề, có thể mở rộng hoặc liên hệ ngắn gọn', 'Đưa ra luận điểm mới chưa bàn ở thân bài', 'Chép lại nguyên văn mở bài', 'Liệt kê thêm dẫn chứng'], ex('Kết bài "khép" vấn đề lại. Đưa luận điểm mới vào kết bài làm bài thiếu cân đối, vì luận điểm phải được chứng minh ở thân bài.'));
add(ST, 4, 'Trong thân bài nghị luận, mỗi đoạn văn nên…', ['triển khai một luận điểm (một ý lớn)', 'chứa tất cả các luận điểm', 'chỉ có một câu', 'nhắc lại mở bài'], ex('Nguyên tắc "mỗi đoạn một ý" giúp người chấm dễ theo dõi. Hết một luận điểm thì xuống dòng sang đoạn mới, mở đầu bằng câu chủ đề.'));
add(ST, 3, 'Đề yêu cầu "viết đoạn văn khoảng 200 chữ". Hình thức nào là đúng?', ['Một đoạn duy nhất: viết hoa lùi đầu dòng, kết thúc bằng dấu chấm, không xuống dòng giữa chừng', 'Ba đoạn: mở, thân, kết', 'Gạch đầu dòng từng ý', 'Viết bao nhiêu đoạn cũng được'], ex('Đoạn văn chỉ có một lần xuống dòng ở cuối. Viết thành nhiều đoạn là thành bài văn ngắn và bị trừ điểm hình thức. Gạch đầu dòng là dàn ý, không phải đoạn văn.'));
add(ST, 3, 'Trình tự đúng của các bước tạo lập văn bản là…', ['Tìm hiểu đề → tìm ý, lập dàn ý → viết → đọc lại và sửa', 'Viết → tìm hiểu đề → lập dàn ý → sửa', 'Lập dàn ý → viết → tìm hiểu đề', 'Viết luôn, không cần chuẩn bị'], ex('Phải hiểu đề (kiểu bài, vấn đề, phạm vi) trước thì mới tìm ý đúng. Bỏ qua bước tìm hiểu đề là nguyên nhân hàng đầu của lỗi lạc đề.'));
add(ST, 4, 'Câu nào làm câu chuyển ý giữa hai luận điểm "Tự học giúp hiểu sâu kiến thức" và "Tự học rèn tính tự lập"?', ['Không chỉ giúp hiểu sâu kiến thức, tự học còn rèn cho ta tính tự lập.', 'Tóm lại, tự học rất quan trọng.', 'Tự học là gì?', 'Có nhiều người không thích tự học.'], ex('Câu chuyển ý nhắc lại ý cũ và mở ra ý mới, thường dùng cấu trúc "không chỉ… mà còn…", "bên cạnh… còn…". "Tóm lại" là từ dùng để kết, không dùng để chuyển.'));
add(ST, 5, 'Sắp xếp thành đoạn diễn dịch: (a) Một cuốn sách hay có thể thay đổi cách ta nhìn cuộc sống. (b) Đọc sách mang lại cho ta rất nhiều lợi ích. (c) Sách giúp ta mở rộng hiểu biết về thế giới. (d) Sách còn bồi dưỡng tâm hồn, dạy ta biết yêu thương.', ['b – c – d – a', 'a – b – c – d', 'c – d – a – b', 'd – c – b – a'], ex('Đoạn diễn dịch phải mở bằng câu khái quát nhất: (b) "rất nhiều lợi ích". Tiếp theo các lợi ích cụ thể (c), (d) — có từ "còn" nên (d) đứng sau (c). Câu (a) nâng ý ở cuối.'));
add(ST, 5, 'Câu nào lạc chủ đề trong đoạn văn bàn về lợi ích của thể thao? "(1) Thể thao giúp cơ thể khoẻ mạnh. (2) Chơi thể thao đồng đội dạy ta tinh thần hợp tác. (3) Giá vé xem bóng đá ngày càng đắt. (4) Vận động đều đặn còn giúp giảm căng thẳng."', ['Câu (3)', 'Câu (1)', 'Câu (2)', 'Câu (4)'], ex('Mọi câu trong đoạn phải phục vụ chủ đề "lợi ích của thể thao". Câu (3) nói về giá vé, không liên quan → lạc chủ đề. Khi viết, hãy hỏi mỗi câu: "câu này có làm rõ ý chính không?"'));
add(ST, 4, 'Bài văn phân tích một tác phẩm truyện thường có bố cục…', ['Mở bài giới thiệu tác giả, tác phẩm, vấn đề; thân bài phân tích chủ đề và nét nghệ thuật; kết bài đánh giá', 'Mở bài kể tóm tắt truyện; thân bài kể tiếp; kết bài kể đoạn kết', 'Chỉ cần kể lại truyện thật hay', 'Mở bài nêu bài học; thân bài kể tiểu sử'], ex('Nghị luận văn học là phân tích và đánh giá, không phải kể lại. Chỉ được tóm tắt ngắn khi cần dẫn dắt, phần chính phải là phân tích nhân vật, chi tiết, nghệ thuật.'));
add(ST, 3, 'Lập dàn ý trước khi viết giúp ích gì nhiều nhất?', ['Sắp xếp ý mạch lạc, không bỏ sót hay lặp ý, phân bổ thời gian hợp lí', 'Làm bài dài hơn', 'Không cần đọc đề', 'Thay cho việc viết bài'], ex('Trong phòng thi, chỉ cần 3–5 phút gạch dàn ý ra nháp là tránh được lỗi lan man, lặp ý và thiếu ý. Dàn ý không thay thế bài viết.'));
add(ST, 5, 'Đoạn văn sau thuộc kiểu nào? "Nguyễn Du đã vẽ bức tranh xuân bằng những nét chấm phá tinh tế. Cỏ non xanh trải tới tận chân trời, gợi sự mênh mông. Trên nền xanh ấy điểm vài bông lê trắng, tạo nên sự hài hoà. Bằng bút pháp ước lệ, nhà thơ đã làm sống dậy cả một mùa xuân trong trẻo, tràn đầy sức sống."', ['Tổng – phân – hợp', 'Quy nạp', 'Song song', 'Móc xích'], ex('Câu đầu khái quát (tổng), hai câu giữa phân tích chi tiết (phân), câu cuối đánh giá, nâng ý (hợp). Đây là kiểu đoạn rất nên dùng khi viết nghị luận văn học.'));
add(ST, 4, 'Để tránh lỗi lặp từ khi viết, cách nào là hợp lí?', ['Dùng phép thế (đại từ, từ đồng nghĩa) cho những từ đã nhắc ở câu trước', 'Bỏ hết chủ ngữ', 'Viết toàn câu rất ngắn', 'Không bao giờ nhắc lại từ khoá'], ex('Phép thế giúp liên kết mà không nhàm (ví dụ: "Nguyễn Du… Nhà thơ… Ông…"). Lưu ý: nhắc lại từ khoá có chủ đích (phép lặp) vẫn tốt; chỉ lặp vô ý mới là lỗi.'));
add(ST, 5, 'Một bài văn có mở bài nêu vấn đề "lòng biết ơn", nhưng thân bài chủ yếu bàn về "tinh thần đoàn kết". Lỗi lớn nhất là gì?', ['Thân bài không thống nhất với mở bài (lạc đề, thiếu mạch lạc)', 'Mở bài quá ngắn', 'Kết bài quá dài', 'Dùng nhiều dẫn chứng'], ex('Các phần trong bài phải cùng hướng về một vấn đề. Mở bài hứa hẹn một đằng, thân bài làm một nẻo là lỗi mạch lạc nghiêm trọng, thường bị chấm là lạc đề.'));

// ── Thể thơ, vần, nhịp ───────────────────────────────────────
const PF = 'lit.poetry-forms';
add(PF, 3, 'Theo luật bằng trắc của thể lục bát, các tiếng thứ 2, 6, 8 thường mang thanh gì?', ['Thanh bằng; tiếng thứ 4 mang thanh trắc', 'Thanh trắc; tiếng thứ 4 mang thanh bằng', 'Tất cả đều thanh trắc', 'Không có quy định'], ex('Thanh bằng = thanh ngang và thanh huyền; thanh trắc = sắc, hỏi, ngã, nặng. Ví dụ "Trăm năm trong cõi người ta": năm (B) – cõi (T) – ta (B). Nhớ: "2 bằng – 4 trắc – 6 bằng".'));
add(PF, 4, 'Trong câu bát của thể lục bát, tiếng thứ 6 và tiếng thứ 8 đều thanh bằng nhưng phải…', ['khác nhau: một tiếng thanh huyền, một tiếng thanh ngang', 'cùng là thanh huyền', 'cùng là thanh ngang', 'là hai tiếng giống hệt nhau'], ex('Ví dụ: "Chữ tài chữ mệnh khéo là ghét nhau": "là" (huyền) – "nhau" (ngang). Sự luân phiên này làm câu bát êm mà không đơn điệu.'));
add(PF, 3, 'Thể lục bát thường ngắt nhịp như thế nào?', ['Nhịp chẵn, phổ biến là 2/2/2 hoặc 4/4', 'Luôn ngắt nhịp 4/3', 'Luôn ngắt nhịp 3/4', 'Không có nhịp'], ex('Lục bát có số tiếng chẵn nên thiên về nhịp chẵn: "Trăm năm / trong cõi / người ta". Nhịp 4/3 là của thơ thất ngôn Đường luật; nhịp 3/4 hay gặp ở câu thất của song thất lục bát.'));
add(PF, 4, '"Trăm năm trong cõi người ta, / Chữ tài chữ mệnh khéo là ghét nhau. / Trải qua một cuộc bể dâu, / Những điều trông thấy mà đau đớn lòng." (Nguyễn Du) — tiếng "dâu" vần với những tiếng nào?', ['"nhau" (tiếng 8 câu bát trước) và "đau" (tiếng 6 câu bát sau)', 'chỉ vần với "ta"', '"là" và "lòng"', 'không vần với tiếng nào'], ex('Cách gieo vần lục bát: tiếng 6 câu lục vần với tiếng 6 câu bát (ta – là); tiếng 8 câu bát vần với tiếng 6 câu lục tiếp theo (nhau – dâu), rồi lại vần tiếng 6 câu bát (dâu – đau). Vần cứ thế nối tiếp như một sợi xích.'));
add(PF, 4, 'Trong thể lục bát, tiếng thứ 6 câu lục vần với tiếng thứ 6 câu bát. Kiểu vần này gọi là…', ['Vần lưng', 'Vần chân', 'Vần liền', 'Không phải vần'], ex('Vần chân: tiếng vần nằm ở cuối dòng. Vần lưng: tiếng vần nằm ở giữa dòng. Tiếng 6 của câu bát nằm giữa câu (câu bát có 8 tiếng) nên là vần lưng; còn tiếng 8 câu bát vần với tiếng 6 câu lục sau là vần chân.'));
add(PF, 5, '"Cùng trông lại mà cùng chẳng thấy, / Thấy xanh xanh những mấy ngàn dâu. / Ngàn dâu xanh ngắt một màu, / Lòng chàng ý thiếp ai sầu hơn ai?" (Chinh phụ ngâm, bản diễn Nôm) — cách gieo vần nào đúng với thể song thất lục bát?', ['"thấy" vần "mấy"; "dâu" vần "màu"; "màu" vần "sầu"', '"thấy" vần "dâu"; "màu" vần "ai"', 'Chỉ có vần ở cuối mỗi câu', 'Đoạn thơ không có vần'], ex('Song thất lục bát: tiếng 7 câu thất đầu (trắc) vần với tiếng 5 câu thất sau (thấy – mấy); tiếng 7 câu thất sau (bằng) vần với tiếng 6 câu lục (dâu – màu); tiếng 6 câu lục vần với tiếng 6 câu bát (màu – sầu). Thể thơ này kết hợp vần trắc và vần bằng, vần lưng và vần chân.'));
add(PF, 4, 'Câu thất trong thể song thất lục bát thường ngắt nhịp…', ['3/4 (ví dụ: "Cùng trông lại / mà cùng chẳng thấy")', '4/3 như thơ Đường', '2/2/2', '1/6'], ex('Khác thơ Đường luật (nhịp 4/3), câu bảy chữ của song thất lục bát thường mở đầu bằng 3 tiếng rồi đến 4 tiếng. Đây là đặc điểm riêng giúp phân biệt hai thể thơ khi gặp câu 7 chữ.'));
add(PF, 3, 'Một bài thất ngôn bát cú Đường luật có tổng cộng bao nhiêu chữ?', ['56 chữ', '28 chữ', '40 chữ', '64 chữ'], ex('Bát cú = 8 câu, thất ngôn = 7 chữ mỗi câu → 8 × 7 = 56. Thất ngôn tứ tuyệt có 4 × 7 = 28 chữ.'));
add(PF, 4, '"Qua Đèo Ngang" (Bà Huyện Thanh Quan) gieo vần ở cuối các câu 1, 2, 4, 6, 8 (tà – hoa – nhà – gia – ta). Đặc điểm vần này là…', ['Vần chân, vần bằng, một vần xuyên suốt bài (độc vận)', 'Vần lưng, vần trắc', 'Mỗi cặp câu đổi một vần', 'Vần ở câu lẻ'], ex('Thơ thất ngôn bát cú Đường luật thường gieo một vần bằng duy nhất ở cuối các câu 1, 2, 4, 6, 8. Các tiếng "tà, hoa, nhà, gia, ta" đều thanh bằng, cùng vần "a".'));
add(PF, 5, 'Câu đầu "Qua Đèo Ngang" là "Bước tới Đèo Ngang, bóng xế tà". Căn cứ vào tiếng thứ hai ("tới"), bài thơ làm theo…', ['Luật trắc', 'Luật bằng', 'Thể lục bát', 'Thể tự do'], ex('Luật của bài Đường luật xác định theo thanh của tiếng thứ 2 câu 1: "tới" có dấu sắc (trắc) → luật trắc. Ngược lại, "Thu điếu" mở đầu "Ao thu…", "thu" thanh bằng → luật bằng.'));
add(PF, 5, 'Trong thơ thất ngôn bát cú Đường luật, "niêm" là sự gắn kết bằng trắc giữa các cặp câu nào?', ['Câu 1–8, 2–3, 4–5, 6–7 (tiếng thứ hai cùng thanh)', 'Câu 1–2, 3–4, 5–6, 7–8', 'Chỉ câu 3–4 và 5–6', 'Câu 1 với tất cả các câu'], ex('Niêm = "dính": tiếng thứ 2 của hai câu niêm với nhau phải cùng thanh (cùng bằng hoặc cùng trắc). Đừng nhầm với "đối": đối là cặp câu thực (3–4) và cặp câu luận (5–6) phải đối ý, đối từ.'));
add(PF, 4, '"Bánh trôi nước" (Hồ Xuân Hương) gieo vần ở các tiếng nào?', ['"tròn", "non", "son" (cuối câu 1, 2, 4)', 'Cuối cả bốn câu', 'Chỉ câu 2 và 4', 'Bài thơ không có vần'], ex('Thất ngôn tứ tuyệt thường gieo vần bằng ở cuối câu 1, 2, 4; câu 3 kết bằng thanh trắc ("nặn") để tạo sự chuyển ý. Cách gieo vần này giống bốn câu đầu của bài bát cú.'));
add(PF, 4, 'Câu thơ thất ngôn Đường luật thường ngắt nhịp…', ['4/3 (ví dụ: "Ao thu lạnh lẽo / nước trong veo")', '3/4', '2/2/2/2', '6/1'], ex('Nhịp 4/3 là nhịp chuẩn của câu thơ Đường. Đôi khi các nhà thơ phá nhịp để tạo hiệu quả riêng, nhưng nếu đề hỏi "nhịp thường gặp" thì đáp án là 4/3. Nhịp 3/4 đặc trưng cho câu thất của song thất lục bát.'));
add(PF, 5, '"Cảnh ngày hè" (Bảo kính cảnh giới, số 43) của Nguyễn Trãi có câu đầu và câu cuối chỉ 6 chữ, các câu còn lại 7 chữ. Thể thơ này gọi là…', ['Thất ngôn xen lục ngôn', 'Lục bát', 'Song thất lục bát', 'Thất ngôn bát cú chuẩn mực'], ex('Đây là sáng tạo của thơ Nôm thời đầu: đưa câu 6 chữ xen vào bài thơ 7 chữ, tạo nhịp điệu dân tộc riêng. Bài thơ có 8 câu nhưng không hoàn toàn theo luật Đường nên không gọi là thất ngôn bát cú chuẩn mực.'));
add(PF, 3, 'Bài "Ánh trăng" của Nguyễn Duy được viết theo thể thơ nào?', ['Năm chữ', 'Lục bát', 'Bảy chữ', 'Song thất lục bát'], ex('Mỗi dòng của bài thơ có 5 chữ → thơ năm chữ. "Sang thu" (Hữu Thỉnh) và "Mùa xuân nho nhỏ" (Thanh Hải) cũng là thơ năm chữ. Mẹo: đếm số tiếng của vài dòng là biết.'));
add(PF, 3, 'Bài "Đồng chí" của Chính Hữu được viết theo thể thơ nào?', ['Tự do', 'Lục bát', 'Thất ngôn bát cú', 'Năm chữ'], ex('Số chữ mỗi dòng không đều (có dòng chỉ 2 chữ, có dòng 7–8 chữ) và không theo khuôn vần cố định → thơ tự do. Thơ tự do vẫn có thể có vần, có nhịp, nhưng không bị gò bó.'));
add(PF, 4, 'Bài "Đoàn thuyền đánh cá" của Huy Cận được viết theo thể thơ nào?', ['Bảy chữ (mỗi khổ bốn câu)', 'Lục bát', 'Năm chữ', 'Tự do'], ex('Mỗi dòng 7 chữ, chia thành các khổ 4 câu → thơ bảy chữ hiện đại. Đừng nhầm với thất ngôn Đường luật: thơ bảy chữ hiện đại không bắt buộc niêm, đối chặt chẽ và có nhiều khổ.'));
add(PF, 3, 'Phần lớn ca dao Việt Nam được sáng tác theo thể thơ nào?', ['Lục bát', 'Song thất lục bát', 'Thất ngôn tứ tuyệt', 'Thơ tự do'], ex('Lục bát là thể thơ thuần Việt, gắn bó với ca dao, dân ca (ví dụ: "Công cha như núi Thái Sơn…"). Thất ngôn tứ tuyệt bắt nguồn từ thơ Đường của Trung Quốc.'));

// ── Truyện: ngôi kể, điểm nhìn, nhân vật ─────────────────────
const NR = 'lit.narrative';
const XE_BUYT = `Chuyến xe buýt cuối ngày vắng khách. Minh ngồi ở hàng ghế cuối, ôm khư khư chiếc cặp có tờ bài kiểm tra bị điểm bốn. Cậu nghĩ đến ánh mắt của bố, đến cái nhíu mày quen thuộc mỗi khi bố thất vọng. Mỗi trạm dừng, cậu lại mong xe đi chậm thêm một chút.

Xe dừng ở trạm gần nhà. Dưới cột đèn, bố đã đứng đợi từ bao giờ, áo còn dính bụi xi măng. Thấy Minh, bố chỉ cười:
— Đói chưa? Về nhà mẹ nấu canh cua.
Minh bỗng thấy cổ họng nghẹn lại.
(Truyện ngắn tự viết)`;
const xb = { passage: XE_BUYT, setId: 'lit-g9b-xe-buyt' };
add(NR, 3, 'Văn bản được kể theo ngôi thứ mấy?', ['Ngôi thứ ba', 'Ngôi thứ nhất', 'Ngôi thứ hai', 'Kết hợp ngôi thứ nhất và thứ hai'], { ...xb, ...ex('Người kể giấu mình, gọi tên nhân vật ("Minh", "cậu", "bố") → ngôi thứ ba. Nếu người kể xưng "tôi" và tham gia câu chuyện thì mới là ngôi thứ nhất.') });
add(NR, 4, 'Câu chuyện được nhìn chủ yếu qua điểm nhìn của ai?', ['Nhân vật Minh', 'Người bố', 'Người mẹ', 'Bác lái xe'], { ...xb, ...ex('Người kể biết Minh nghĩ gì ("cậu nghĩ đến ánh mắt của bố", "mong xe đi chậm"), còn bố thì chỉ được tả qua những gì Minh thấy. Ngôi thứ ba nhưng điểm nhìn đặt vào bên trong nhân vật Minh.') });
add(NR, 4, 'Chi tiết "Mỗi trạm dừng, cậu lại mong xe đi chậm thêm một chút" thể hiện điều gì?', ['Minh lo sợ, muốn trì hoãn lúc phải gặp bố', 'Minh thích đi xe buýt', 'Minh bị say xe', 'Minh muốn ngắm phố'], { ...xb, ...ex('Đặt chi tiết vào hoàn cảnh: Minh mang bài điểm kém, đang nghĩ tới sự thất vọng của bố. Muốn xe chậm lại = muốn kéo dài thời gian trước khi phải đối mặt. Chi tiết nhỏ nhưng diễn tả tâm lí rất thật.') });
add(NR, 4, 'Chi tiết "áo còn dính bụi xi măng" gợi điều gì về người bố?', ['Bố làm việc vất vả, chưa kịp nghỉ đã ra đón con', 'Bố không quan tâm đến vẻ ngoài', 'Bố vừa đi du lịch về', 'Bố đang giận Minh'], { ...xb, ...ex('Chi tiết nghệ thuật thường "nói" nhiều hơn nghĩa đen. Bụi xi măng cho thấy bố đi làm công việc nặng nhọc, rồi đi thẳng ra trạm xe. Điều này làm sự ân cần của bố càng cảm động.') });
add(NR, 3, 'Câu "— Đói chưa? Về nhà mẹ nấu canh cua." là…', ['Lời nhân vật (lời đối thoại của người bố)', 'Lời người kể chuyện', 'Lời độc thoại nội tâm của Minh', 'Lời tác giả bình luận'], { ...xb, ...ex('Câu đặt sau dấu gạch đầu dòng, là lời bố nói ra thành tiếng với Minh → lời nhân vật (đối thoại). Độc thoại nội tâm là lời nhân vật tự nói với chính mình, không phát ra cho người khác nghe.') });
add(NR, 5, 'Vì sao ở cuối truyện Minh "thấy cổ họng nghẹn lại"?', ['Minh chuẩn bị tinh thần bị trách mắng nhưng lại nhận được sự ân cần, nên xúc động và thấy có lỗi', 'Minh bị ốm', 'Minh ghét món canh cua', 'Minh giận bố vì bố đến muộn'], { ...xb, ...ex('Truyện xây dựng một sự đối lập: điều Minh lo sợ (bố thất vọng) và điều xảy ra thật (bố chỉ hỏi con đói chưa). Khoảng cách ấy tạo nên cảm xúc ở kết truyện. Đọc kết truyện luôn phải đặt cạnh tâm trạng ở đầu truyện.') });
add(NR, 3, '"Chiếc lược ngà" (Nguyễn Quang Sáng) được kể theo ngôi thứ nhất, người kể chuyện là…', ['Bác Ba, người đồng đội của ông Sáu', 'Bé Thu', 'Ông Sáu', 'Mẹ của bé Thu'], ex('Người kể xưng "tôi" là bác Ba, người chứng kiến câu chuyện cha con ông Sáu. Nhờ đứng ngoài, người kể vừa kể khách quan vừa bộc lộ được sự xúc động của người chứng kiến. Đây là câu hay bị nhầm thành "ông Sáu kể".'));
add(NR, 3, 'Truyện "Những ngôi sao xa xôi" (Lê Minh Khuê) được kể từ ngôi kể và điểm nhìn của ai?', ['Ngôi thứ nhất, nhân vật Phương Định', 'Ngôi thứ ba, người kể giấu mình', 'Ngôi thứ nhất, chị Thao', 'Ngôi thứ nhất, Nho'], ex('Phương Định xưng "tôi" kể về mình và hai đồng đội Thao, Nho. Kể từ bên trong giúp tác giả miêu tả tâm lí tinh tế của cô gái trẻ nơi chiến trường.'));
add(NR, 4, 'Tình huống truyện cơ bản của "Làng" (Kim Lân) là…', ['Ông Hai nghe tin làng Chợ Dầu của mình theo giặc', 'Ông Hai đi tản cư lần đầu', 'Ông Hai gặp lại con sau nhiều năm', 'Ông Hai được bầu làm trưởng thôn'], ex('Tình huống truyện là hoàn cảnh đặc biệt làm bộc lộ rõ nhất nhân vật. Ông Hai yêu làng tha thiết, nên cái tin làng theo giặc đặt ông vào mâu thuẫn giữa tình yêu làng và lòng yêu nước. Gặp lại con sau nhiều năm là tình huống của "Chiếc lược ngà".'));
add(NR, 4, '"Tình huống truyện" là gì?', ['Hoàn cảnh, sự việc đặc biệt mà nhân vật bị đặt vào, qua đó tính cách và chủ đề bộc lộ', 'Tên của truyện', 'Phần mở đầu giới thiệu nhân vật', 'Lời bình của tác giả ở cuối truyện'], ex('Tình huống càng éo le, nhân vật càng bộc lộ rõ. Khi phân tích truyện ngắn, câu hỏi đầu tiên nên đặt là: tình huống ở đây là gì, nó làm nhân vật hiện lên ra sao?'));
add(NR, 4, 'Kết thúc "Chuyện người con gái Nam Xương": Vũ Nương hiện về giữa dòng sông rồi biến mất, không trở lại trần gian. Kết thúc này có ý nghĩa gì?', ['Vừa thoả mong ước công bằng cho người tốt, vừa khẳng định bi kịch: hạnh phúc đã mất không thể tìm lại', 'Chỉ là kết thúc có hậu trọn vẹn', 'Cho thấy Vũ Nương không còn thương chồng con', 'Không có ý nghĩa gì, chỉ để truyện hấp dẫn'], ex('Yếu tố kì ảo giúp Vũ Nương được minh oan (phần "có hậu"), nhưng nàng không thể quay về (phần bi kịch). Chọn "kết thúc có hậu trọn vẹn" là bỏ qua tính bi kịch, cũng là giá trị tố cáo của tác phẩm.'));
add(NR, 5, 'Trong "Chuyện người con gái Nam Xương", vì sao Trương Sinh nghi oan cho vợ?', ['Vì lời bé Đản nói về "người cha" đêm nào cũng đến (thực ra là cái bóng), cộng với tính đa nghi của Trương Sinh', 'Vì Vũ Nương bỏ nhà đi', 'Vì hàng xóm vu khống', 'Vì Phan Lang kể lại'], ex('Nguyên nhân trực tiếp là chi tiết "cái bóng" (lời trẻ thơ ngây). Nguyên nhân sâu xa là tính đa nghi của Trương Sinh và xã hội phong kiến cho người chồng quyền định đoạt. Phan Lang chỉ xuất hiện sau khi Vũ Nương đã mất.'));
add(NR, 3, '"Độc thoại nội tâm" trong truyện là…', ['Lời nhân vật tự nói với chính mình, thể hiện suy nghĩ bên trong', 'Lời hai nhân vật nói với nhau', 'Lời người kể giới thiệu bối cảnh', 'Lời ghi chú của nhà xuất bản'], ex('Đối thoại: hai người trở lên nói với nhau. Độc thoại: nói một mình (có thể thành tiếng). Độc thoại nội tâm: lời diễn ra trong đầu, thường xuất hiện ở những lúc nhân vật giằng co, day dứt.'));
add(NR, 5, 'So với ngôi thứ ba, ưu thế lớn nhất của ngôi kể thứ nhất là gì?', ['Tạo cảm giác chân thực, dễ đi sâu vào cảm xúc của người kể', 'Kể được suy nghĩ của mọi nhân vật', 'Luôn khách quan hơn', 'Làm truyện ngắn hơn'], ex('Người kể xưng "tôi" kể điều mình trải qua nên gần gũi, thật. Hạn chế là "tôi" không biết hết suy nghĩ của người khác. Kể được suy nghĩ của mọi nhân vật là ưu thế của ngôi thứ ba toàn tri.'));
add(NR, 4, '"Hoàng Lê nhất thống chí" (Ngô gia văn phái) thuộc thể loại nào?', ['Tiểu thuyết lịch sử chương hồi, viết bằng chữ Hán', 'Truyện thơ Nôm lục bát', 'Truyện truyền kì', 'Truyện ngắn hiện đại'], ex('Tác phẩm gồm nhiều hồi, ghi lại biến cố lịch sử cuối thế kỉ XVIII; hồi thứ mười bốn kể việc Quang Trung đại phá quân Thanh. Viết bằng chữ Hán, nhưng không có yếu tố kì ảo như truyện truyền kì.'));
add(NR, 5, 'Trong truyện "Làng", câu chuyện được kể ở ngôi thứ ba nhưng người đọc hiểu rõ từng day dứt của ông Hai. Đó là nhờ…', ['Người kể đặt điểm nhìn vào nhân vật, kết hợp miêu tả nội tâm và độc thoại', 'Ông Hai tự xưng "tôi" kể chuyện', 'Tác giả viết lời bình sau mỗi đoạn', 'Truyện có yếu tố kì ảo'], ex('Ngôi thứ ba không có nghĩa là chỉ kể bên ngoài. Người kể có thể "nhập" vào nhân vật, thuật lại suy nghĩ, cảm xúc, thậm chí cả những cuộc trò chuyện của nhân vật với chính mình (ông Hai nói chuyện với đứa con út).'));
add(NR, 3, 'Nhân vật Lục Vân Tiên trong truyện thơ cùng tên của Nguyễn Đình Chiểu là hình mẫu…', ['người anh hùng trọng nghĩa, sẵn sàng cứu người gặp nạn', 'kẻ tham lam, bội bạc', 'nhà buôn giàu có', 'ông quan độc ác'], ex('Lục Vân Tiên đánh cướp cứu Kiều Nguyệt Nga mà không màng báo đáp, thể hiện lí tưởng "kiến nghĩa bất vi vô dũng" (thấy việc nghĩa mà không làm là không có dũng khí). Kẻ bội bạc là các nhân vật phản diện như Trịnh Hâm, Bùi Kiệm.'));

// ── Tác giả, tác phẩm văn học trung đại ─────────────────────
const CL = 'lit.classics';
add(CL, 3, '"Tố Như" là tên hiệu của nhà thơ nào?', ['Nguyễn Du', 'Nguyễn Trãi', 'Nguyễn Khuyến', 'Nguyễn Đình Chiểu'], ex('Nguyễn Du (1765–1820), tên chữ Tố Như, hiệu Thanh Hiên. Nguyễn Trãi hiệu Ức Trai; Nguyễn Đình Chiểu thường được gọi là Đồ Chiểu. Nhớ cặp: Tố Như – Nguyễn Du, Ức Trai – Nguyễn Trãi.'));
add(CL, 3, 'Quê hương của Nguyễn Du ở đâu?', ['Làng Tiên Điền, huyện Nghi Xuân, Hà Tĩnh', 'Làng Yên Đổ, Bình Lục, Hà Nam', 'Làng Nhị Khê, Thường Tín, Hà Nội', 'Gia Định (nay là TP Hồ Chí Minh)'], ex('Nguyễn Du quê Tiên Điền (Hà Tĩnh) nhưng sinh ở Thăng Long. Yên Đổ là quê Nguyễn Khuyến; Nhị Khê là quê Nguyễn Trãi; Gia Định là quê Nguyễn Đình Chiểu.'));
add(CL, 4, 'Nguyễn Du đặt cho tác phẩm của mình tên chữ Hán là gì?', ['Đoạn trường tân thanh', 'Kim Vân Kiều truyện', 'Truyền kì mạn lục', 'Ức Trai thi tập'], ex('"Đoạn trường tân thanh" nghĩa là "tiếng kêu mới về nỗi đau đứt ruột". Tên quen gọi "Truyện Kiều" có sau. "Kim Vân Kiều truyện" là tiểu thuyết của Thanh Tâm Tài Nhân (Trung Quốc), nguồn cốt truyện mà Nguyễn Du dựa vào.'));
add(CL, 4, '"Truyện Kiều" có bao nhiêu câu thơ lục bát?', ['3254 câu', '1254 câu', '2054 câu', '4254 câu'], ex('Truyện Kiều có 3254 câu (1627 cặp lục bát). Đây là dữ kiện hay xuất hiện ở câu hỏi nhận biết. Mẹo nhớ: "ba hai năm bốn".'));
add(CL, 3, 'Nhan đề "Truyền kì mạn lục" của Nguyễn Dữ có nghĩa là…', ['Ghi chép tản mạn những chuyện kì lạ được lưu truyền', 'Truyện về các vị vua', 'Thơ ca dân gian', 'Sách dạy làm quan'], ex('Truyền kì = truyện kì lạ được lưu truyền; mạn lục = ghi chép tản mạn. Tập truyện viết bằng chữ Hán ở thế kỉ XVI, gồm 20 truyện, trong đó có "Chuyện người con gái Nam Xương".'));
add(CL, 4, 'Điều nào đúng về Nguyễn Đình Chiểu?', ['Ông bị mù nhưng vẫn dạy học, bốc thuốc và sáng tác thơ văn yêu nước bằng chữ Nôm', 'Ông là tác giả "Truyện Kiều"', 'Ông viết chủ yếu bằng chữ Pháp', 'Ông là vua triều Lê'], ex('Nguyễn Đình Chiểu (1822–1888) bị mù từ khi còn trẻ. Ông viết "Truyện Lục Vân Tiên", "Văn tế nghĩa sĩ Cần Giuộc" bằng chữ Nôm. Ngòi bút của ông gắn với cuộc kháng chiến chống Pháp ở Nam Bộ.'));
add(CL, 4, 'Tập thơ viết bằng chữ Nôm của Nguyễn Trãi là…', ['Quốc âm thi tập', 'Ức Trai thi tập', 'Bình Ngô đại cáo', 'Truyền kì mạn lục'], ex('"Quốc âm" = tiếng nước mình (tức chữ Nôm). "Ức Trai thi tập" là tập thơ chữ Hán; "Bình Ngô đại cáo" là bài cáo viết bằng chữ Hán. Bài "Cảnh ngày hè" nằm trong "Quốc âm thi tập".'));
add(CL, 4, '"Bình Ngô đại cáo" của Nguyễn Trãi thường được gọi là…', ['Bản tuyên ngôn độc lập thứ hai của dân tộc', 'Bản tuyên ngôn độc lập đầu tiên', 'Truyện thơ Nôm đầu tiên', 'Bài hịch kêu gọi tướng sĩ'], ex('"Nam quốc sơn hà" thường được coi là bản tuyên ngôn độc lập đầu tiên; "Bình Ngô đại cáo" (1428) là bản thứ hai; "Tuyên ngôn Độc lập" (1945) là bản thứ ba. Bài hịch kêu gọi tướng sĩ là "Hịch tướng sĩ" của Trần Quốc Tuấn.'));
add(CL, 4, 'Bài "Nam quốc sơn hà" (tương truyền của Lý Thường Kiệt) được viết bằng…', ['Chữ Hán, thể thất ngôn tứ tuyệt', 'Chữ Nôm, thể lục bát', 'Chữ quốc ngữ, thể tự do', 'Chữ Hán, thể song thất lục bát'], ex('Bài thơ 4 câu × 7 chữ bằng chữ Hán (mở đầu "Nam quốc sơn hà Nam đế cư"). Thời Lý chưa có văn học chữ Nôm phát triển; song thất lục bát là thể thơ thuần Việt xuất hiện muộn hơn nhiều.'));
add(CL, 4, 'Về "Chinh phụ ngâm", nhận định nào đúng?', ['Nguyên tác chữ Hán của Đặng Trần Côn; bản diễn Nôm song thất lục bát thường được cho là của Đoàn Thị Điểm', 'Nguyên tác chữ Nôm của Nguyễn Du', 'Do Hồ Xuân Hương viết bằng thể Đường luật', 'Là truyện ngắn hiện đại'], ex('Đặng Trần Côn viết bằng chữ Hán (thế kỉ XVIII). Bản diễn Nôm phổ biến thường được ghi là của Đoàn Thị Điểm (có ý kiến cho là Phan Huy Ích). Tác phẩm nói lên nỗi cô đơn của người vợ có chồng đi chinh chiến.'));
add(CL, 4, '"Cung oán ngâm khúc" là tác phẩm của ai và viết theo thể thơ nào?', ['Nguyễn Gia Thiều, song thất lục bát', 'Nguyễn Du, lục bát', 'Bà Huyện Thanh Quan, Đường luật', 'Nguyễn Khuyến, thất ngôn tứ tuyệt'], ex('Cùng với "Chinh phụ ngâm", "Cung oán ngâm khúc" là hai khúc ngâm nổi tiếng viết bằng song thất lục bát, thể thơ rất hợp để diễn tả nỗi buồn triền miên. Tác phẩm nói về nỗi oán của người cung nữ bị vua ruồng bỏ.'));
add(CL, 3, 'Bài thơ "Thương vợ" là của tác giả nào?', ['Trần Tế Xương (Tú Xương)', 'Nguyễn Khuyến', 'Nguyễn Trãi', 'Hồ Xuân Hương'], ex('Tú Xương (1870–1907), quê Nam Định, nổi tiếng với thơ trào phúng và trữ tình. "Thương vợ" viết về bà Tú tần tảo nuôi chồng con.'));
add(CL, 3, 'Vì sao Nguyễn Khuyến được gọi là "Tam nguyên Yên Đổ"?', ['Vì ông đỗ đầu cả ba kì thi Hương, Hội, Đình và quê ở làng Yên Đổ', 'Vì ông có ba người con', 'Vì ông viết ba bài thơ thu', 'Vì ông làm quan ba triều vua'], ex('"Tam nguyên" = ba lần đỗ đầu (giải nguyên kì thi Hương, hội nguyên kì thi Hội, đình nguyên kì thi Đình). Bẫy: ông có chùm ba bài thơ thu, nhưng biệt danh không đến từ đó.'));
add(CL, 5, 'Nguyễn Du tả Thuý Vân, Thuý Kiều bằng những hình ảnh mây, tuyết, hoa, liễu, nước mùa thu. Đó là bút pháp…', ['Ước lệ tượng trưng: lấy vẻ đẹp thiên nhiên làm chuẩn mực để gợi vẻ đẹp con người', 'Tả thực chi tiết từng đường nét', 'Trào phúng, châm biếm', 'Kì ảo, hoang đường'], ex('Văn học trung đại hay dùng hình ảnh quen thuộc, mang tính quy ước (mai, tuyết, hoa, ngọc) để gợi chứ không tả cụ thể. Ví dụ: "Mai cốt cách tuyết tinh thần". Tả thực từng chi tiết là đặc trưng của văn học hiện đại.'));
add(CL, 5, '"Qua Đèo Ngang" kết bằng "Một mảnh tình riêng, ta với ta"; "Bạn đến chơi nhà" (Nguyễn Khuyến) kết bằng "Bác đến chơi đây, ta với ta". Hai chữ "ta với ta" khác nhau thế nào?', ['Ở Bà Huyện Thanh Quan là một mình đối diện chính mình (cô đơn); ở Nguyễn Khuyến là chủ và khách hoà làm một (tình bạn gắn bó)', 'Cả hai đều chỉ nỗi cô đơn', 'Cả hai đều chỉ tình bạn', 'Không khác nhau, vì dùng cùng một cụm từ'], ex('Cùng một cụm từ nhưng ngữ cảnh làm nghĩa khác hẳn. Bà Huyện Thanh Quan đứng một mình giữa trời, non, nước, nên "ta" và "ta" đều là bản thân. Ở Nguyễn Khuyến, "bác" và "ta" là hai người bạn mà như một. Đây là dạng câu so sánh hay ra ở mức vận dụng cao.'));
add(CL, 4, 'Nét nổi bật nhất trong thơ Nôm của Hồ Xuân Hương là gì?', ['Giọng thơ táo bạo, sắc sảo, cất lên tiếng nói đòi quyền sống và hạnh phúc cho người phụ nữ', 'Viết toàn bằng chữ Hán', 'Chủ yếu ca ngợi vua chúa', 'Chỉ viết thơ tự do'], ex('Hồ Xuân Hương viết thơ Nôm Đường luật nhưng đưa vào đó ngôn ngữ dân gian và cá tính rất mạnh. Ví dụ "Bánh trôi nước" vừa than thân vừa khẳng định phẩm chất "tấm lòng son".'));
add(CL, 5, 'Giá trị nhân đạo của "Truyện Kiều" thể hiện rõ nhất ở điểm nào?', ['Cảm thương số phận con người bị chà đạp, trân trọng vẻ đẹp và khát vọng tình yêu, tự do của họ', 'Ca ngợi quyền lực của đồng tiền', 'Chỉ kể lại một câu chuyện tình', 'Đề cao lối sống hưởng lạc'], ex('Giá trị nhân đạo = tình thương và sự trân trọng con người. Nguyễn Du còn lên án những thế lực vùi dập Kiều, chẳng hạn đồng tiền. Bẫy "ca ngợi đồng tiền" là hiểu ngược, vì tác phẩm phê phán sức mạnh tàn phá của đồng tiền.'));

// ── Từ Hán Việt ──────────────────────────────────────────────
const HV = 'lit.hanviet';
add(HV, 3, 'Trong từ nào, yếu tố "thủ" có nghĩa là "giữ"?', ['thủ môn', 'thủ công', 'thủ đô', 'thủ lĩnh'], ex('Có nhiều chữ "thủ" đồng âm: 守 giữ (thủ môn = người giữ cửa/khung thành, phòng thủ), 手 tay (thủ công = làm bằng tay), 首 đầu (thủ đô, thủ lĩnh). Cách đoán: thay nghĩa vào và xem câu có hợp lí không.'));
add(HV, 3, 'Trong từ nào, "gia" KHÔNG có nghĩa là "nhà"?', ['gia tăng', 'gia đình', 'gia sản', 'gia chủ'], ex('"Gia" (家) là nhà: gia đình, gia sản (tài sản của nhà), gia chủ (chủ nhà). "Gia" trong gia tăng, gia vị là "thêm" (加). Đây là hiện tượng đồng âm khác nghĩa, rất hay gặp trong từ Hán Việt.'));
add(HV, 4, 'Trong từ nào, yếu tố "nhân" KHÔNG mang nghĩa "người"?', ['nguyên nhân', 'nhân loại', 'nhân dân', 'nhân vật'], ex('"Nhân" (人) = người: nhân loại, nhân dân, nhân vật. "Nhân" trong nguyên nhân (因) là "nguyên do". Ngoài ra còn "nhân" (仁) = lòng thương người, như trong nhân hậu, nhân nghĩa.'));
add(HV, 4, 'Từ "thiên vị" có yếu tố "thiên" mang nghĩa gì?', ['Nghiêng lệch về một phía', 'Trời', 'Nghìn', 'Dời đi'], ex('Thiên vị = nghiêng về một bên, không công bằng. Các chữ "thiên" khác: trời (thiên nhiên), nghìn (thiên niên kỉ), dời (thiên di). Khi gặp yếu tố đa nghĩa, hãy dựa vào nghĩa của cả từ để suy ra.'));
add(HV, 3, '"Hồng nhan" (trong văn chương xưa) dùng để chỉ…', ['người con gái đẹp', 'màu đỏ', 'người đàn ông giàu có', 'bông hoa hồng'], ex('Hồng = đỏ, hồng; nhan = mặt, má. Má hồng → hoán dụ chỉ người con gái đẹp. Thành ngữ "hồng nhan bạc mệnh" nói người đẹp thường gặp số phận bất hạnh, đúng với cuộc đời Thuý Kiều.'));
add(HV, 4, 'Trong "bạc mệnh", "bạc" có nghĩa là…', ['mỏng manh, kém may mắn', 'tiền bạc', 'màu trắng', 'bội bạc, vô ơn'], ex('"Bạc" (薄) = mỏng; "mệnh" = số phận. "Bạc mệnh" = phận mỏng, bất hạnh. Cũng chữ "bạc" này mà "bạc tình", "bội bạc" là tình mỏng. Tiền bạc hay tóc bạc là từ thuần Việt hoặc khác chữ.'));
add(HV, 3, 'Cặp từ nào đúng nghĩa: "cố hương" – "tha hương"?', ['quê cũ – quê người', 'quê người – quê cũ', 'quê mới – quê cũ', 'làng – thành phố'], ex('Cố = cũ (cố đô, cố nhân); tha = khác, của người khác. Cố hương = quê cũ, quê nhà; tha hương = nơi đất khách. "Hồi hương" = trở về quê.'));
add(HV, 4, 'Từ "tri kỉ" có nghĩa là…', ['người hiểu rõ mình, bạn rất thân', 'người mình mới quen', 'người dạy học', 'người lạ'], ex('Tri = biết, hiểu; kỉ = mình. Tri kỉ = hiểu mình. Gần nghĩa với "tri âm" (hiểu tiếng đàn, từ tích Bá Nha – Tử Kỳ).'));
add(HV, 5, '"Đoạn trường" trong tên "Đoạn trường tân thanh" có nghĩa là…', ['đứt ruột, chỉ nỗi đau đớn tột cùng', 'đoạn đường dài', 'trường học', 'một đoạn văn'], ex('Đoạn = cắt đứt; trường = ruột (腸), không phải "trường" là trường học hay dài. Nỗi đau như đứt ruột. Bẫy "đoạn đường dài" sinh ra từ việc hiểu theo âm thuần Việt.'));
add(HV, 5, 'Từ "cứu cánh" theo nghĩa gốc là gì?', ['Mục đích cuối cùng', 'Sự cứu giúp kịp thời', 'Cánh tay cứu người', 'Phương tiện thoát hiểm'], ex('Cứu cánh (究竟) = cái đích cuối cùng ("học vấn là phương tiện, không phải cứu cánh"). Nhiều người dùng nhầm thành "chỗ dựa cứu giúp" vì liên tưởng tới "cứu" (giúp). Từ điển hiện nay có ghi nhận nghĩa mới, nhưng trong bài thi nên dùng theo nghĩa gốc.'));
add(HV, 4, 'Câu nào dùng đúng từ?', ['Không thể bàng quan trước nỗi đau của người khác.', 'Không thể bàng quang trước nỗi đau của người khác.', 'Không thể bàn quan trước nỗi đau của người khác.', 'Không thể bàng hoàng quan trước nỗi đau của người khác.'], ex('"Bàng quan" (bàng = bên cạnh, quan = xem) = đứng ngoài nhìn, thờ ơ. "Bàng quang" là một cơ quan trong cơ thể. Hai từ gần âm nên rất dễ viết nhầm.'));
add(HV, 3, 'Viết đúng chính tả: "Lớp em đi ___ Văn Miếu – Quốc Tử Giám."', ['tham quan', 'thăm quan', 'tham quang', 'thăm quang'], ex('Tham quan = xem tận mắt để mở rộng hiểu biết (tham = dự vào, quan = xem). "Thăm quan" là lỗi do lẫn với từ thuần Việt "thăm". Từ điển chuẩn chỉ ghi "tham quan".'));
add(HV, 4, 'Trong từ nào, "phi" có nghĩa là "bay"?', ['phi công', 'phi pháp', 'phi nghĩa', 'phi thường'], ex('"Phi" (飛) = bay: phi công, phi cơ. "Phi" (非) = không phải, trái với: phi pháp (trái pháp luật), phi nghĩa, phi thường (khác thường).'));
add(HV, 4, 'Yếu tố "hữu" trong "hữu ích" có nghĩa là…', ['có', 'bạn', 'bên phải', 'mãi mãi'], ex('Hữu ích = có ích (有). Cùng âm "hữu" còn có: bạn (bằng hữu, 友), bên phải (hữu ngạn = bờ bên phải, 右). Trái nghĩa của "hữu" (có) là "vô" (không): hữu ích – vô ích.'));
add(HV, 5, '"Thạch mã" nghĩa là gì?', ['Ngựa đá', 'Đá của ngựa', 'Ngựa chạy trên đá', 'Mỏ đá'], ex('Trong nhiều từ ghép Hán Việt chính phụ, yếu tố phụ đứng TRƯỚC yếu tố chính, ngược với tiếng Việt: thạch (đá) + mã (ngựa) = ngựa đá; thiên thư = sách trời; "hải cẩu" = chó biển. Biết quy tắc này sẽ đoán được rất nhiều từ.'));
add(HV, 5, 'Câu "Tiệt nhiên định phận tại thiên thư" (Nam quốc sơn hà) có "thiên thư" nghĩa là…', ['sách trời', 'nghìn cuốn sách', 'bức thư của vua', 'trời và đất'], ex('Thiên (trời) + thư (sách) = sách trời (yếu tố phụ đứng trước). Câu thơ khẳng định sự phân định lãnh thổ nước Nam đã được ghi ở sách trời, tức là chân lí không thể thay đổi.'));
add(HV, 4, '"Khán giả", "thính giả", "độc giả" lần lượt là người…', ['xem – nghe – đọc', 'nghe – xem – đọc', 'đọc – nghe – xem', 'xem – đọc – nghe'], ex('"Giả" = người. Khán = xem (khán đài), thính = nghe (thính giác), độc = đọc (độc thoại là nói một mình, khác chữ "độc"). Ghép nghĩa từng yếu tố là cách nhớ nhanh nhất.'));
add(HV, 4, 'Câu nào dùng từ Hán Việt KHÔNG phù hợp sắc thái?', ['Con chó nhà em đã từ trần sau mười năm sống cùng gia đình.', 'Cụ đã từ trần, hưởng thọ 90 tuổi.', 'Các anh hùng liệt sĩ đã hi sinh vì Tổ quốc.', 'Phu nhân Chủ tịch nước tới thăm trường.'], ex('"Từ trần" mang sắc thái trang trọng, chỉ dùng cho người. Dùng cho con vật là sai phong cách. Từ Hán Việt thường tạo sắc thái trang trọng, tôn kính, nên phải dùng đúng đối tượng.'));

// ── Điển tích, điển cố ───────────────────────────────────────
const AL = 'lit.allusion';
add(AL, 3, '"Nằm gai nếm mật" (tích Câu Tiễn nước Việt thời Xuân Thu) chỉ điều gì?', ['Chịu đựng gian khổ, ngày đêm nuôi chí phục thù, khôi phục đất nước', 'Thích ăn đồ ngọt', 'Sống xa hoa, hưởng lạc', 'Người hay ốm đau'], ex('Câu Tiễn thua trận, nằm trên củi gai và nếm mật đắng để không quên mối nhục, cuối cùng đánh bại nước Ngô. Nguyễn Trãi cũng dùng ý này để nói về những năm gian khổ của nghĩa quân Lam Sơn.'));
add(AL, 3, '"Ôm cây đợi thỏ" phê phán kiểu người nào?', ['Bảo thủ, trông chờ may rủi, không chịu lao động', 'Chăm chỉ săn bắt', 'Yêu thương loài vật', 'Kiên trì theo đuổi mục tiêu'], ex('Người nông dân thấy một con thỏ đâm vào gốc cây chết, bèn bỏ cày ngồi chờ con khác. Bẫy "kiên trì": chờ đợi ở đây không phải kiên trì mà là ỷ lại vào may mắn.'));
add(AL, 3, '"Vẽ rắn thêm chân" chỉ điều gì?', ['Làm việc thừa, khiến kết quả hỏng đi', 'Vẽ rất giỏi', 'Làm việc cẩn thận, chu đáo', 'Sáng tạo điều mới'], ex('Người vẽ xong rắn trước tiên, vì muốn khoe nên vẽ thêm chân, rốt cuộc bị thua vì "rắn làm gì có chân". Bài học: làm thừa không làm việc tốt hơn mà còn làm hỏng việc.'));
add(AL, 4, 'Điển "tam cố thảo lư" (Lưu Bị ba lần đến lều cỏ mời Gia Cát Lượng) thường được dùng để nói về…', ['Sự chân thành, kiên trì khi cầu người tài', 'Việc xây nhà bằng cỏ', 'Sự lười biếng', 'Ba lần thất bại'], ex('Tam = ba; cố = thăm, ngoảnh lại; thảo lư = lều cỏ. Lưu Bị hai lần đến không gặp, lần thứ ba mới được gặp và mời được Gia Cát Lượng giúp mình. Điển cố này đề cao việc trọng dụng nhân tài.'));
add(AL, 4, '"Giấc mộng Nam Kha" (hay "giấc hoè") thường gợi ý nghĩa gì?', ['Giàu sang, danh vọng chỉ như một giấc mơ ngắn ngủi', 'Một giấc ngủ ngon', 'Ước mơ chắc chắn thành hiện thực', 'Tình yêu đôi lứa'], ex('Thuần Vu Phần nằm mơ dưới gốc hoè thấy mình làm quan to ở quận Nam Kha, tỉnh dậy mới biết đó chỉ là tổ kiến. Điển này nói sự phù du của công danh, phú quý.'));
add(AL, 4, '"Ông Tơ bà Nguyệt" (Nguyệt lão) trong văn chương là hình ảnh…', ['Vị thần xe duyên vợ chồng', 'Thần mặt trăng', 'Người dệt lụa', 'Hai vợ chồng già nghèo khó'], ex('Theo truyền thuyết, Nguyệt lão ngồi dưới trăng, dùng sợi chỉ hồng buộc chân những người sẽ thành vợ chồng. Từ đó có các cách nói "tơ hồng", "xe duyên", "ông Tơ bà Nguyệt".'));
add(AL, 4, '"Trải qua một cuộc bể dâu, / Những điều trông thấy mà đau đớn lòng." (Nguyễn Du) — "bể dâu" gợi điều gì?', ['Cuộc đời biến đổi lớn lao, dữ dội (biển hoá ruộng dâu, ruộng dâu hoá biển)', 'Một vùng biển trồng dâu', 'Cuộc sống bình yên', 'Nghề nuôi tằm'], ex('"Bể dâu" rút từ thành ngữ "thương hải tang điền" (biển xanh hoá ruộng dâu). Nguyễn Du dùng nó để nói những đổi thay đau đớn của cuộc đời. Hiểu theo nghĩa đen ("vùng biển trồng dâu") là không nhận ra điển cố.'));
add(AL, 5, '"Sân Lai cách mấy nắng mưa, / Có khi gốc tử đã vừa người ôm." (Nguyễn Du) — "sân Lai" và "gốc tử" gợi…', ['cha mẹ, quê nhà nơi cha mẹ đang già đi; thể hiện nỗi nhớ thương, lo lắng của người con', 'một khu vườn đẹp', 'người yêu ở phương xa', 'cảnh chùa chiền'], ex('"Sân Lai": Lão Lai Tử bảy mươi tuổi vẫn mặc áo sặc sỡ múa ở sân cho cha mẹ vui, điển về chữ hiếu. "Gốc tử": cây tử trồng ở quê, chỉ quê hương. Hai câu thơ nói nỗi lo cha mẹ ngày càng già đi khi Kiều không ở bên.'));
add(AL, 5, '"Quạt nồng ấp lạnh" (Truyện Kiều) gợi điển tích về…', ['Người con hiếu thảo: mùa hè quạt màn cho cha, mùa đông ủ ấm chăn chiếu cho cha', 'Nghề làm quạt', 'Thời tiết thất thường', 'Một người lính chăm sóc đồng đội'], ex('Điển Hoàng Hương thời Hán, nổi tiếng hiếu thảo. Trong đoạn ở lầu Ngưng Bích, Kiều xót cha mẹ già không có ai "quạt nồng ấp lạnh", cho thấy nàng hiếu thảo, quên cảnh mình để nghĩ cho người thân.'));
add(AL, 4, '"Nghiêng nước nghiêng thành" dùng để nói về…', ['Sắc đẹp tuyệt trần, có thể làm say đắm cả bậc vua chúa', 'Một trận động đất', 'Thành trì bị phá huỷ', 'Người có sức khoẻ phi thường'], ex('Câu hát xưa (Lý Diên Niên) khen người đẹp: ngoảnh lại nhìn một lần thì nghiêng thành, nhìn lần nữa thì nghiêng nước. Nguyễn Du dùng ý này khi tả Kiều: "Một hai nghiêng nước nghiêng thành".'));
add(AL, 4, '"Ngu Công dời núi" là biểu tượng của…', ['Sự kiên trì, bền bỉ thì việc khó mấy cũng làm được', 'Sự ngu dốt', 'Việc phá hoại thiên nhiên', 'Sự vội vàng'], ex('Ông lão Ngu Công quyết đào hai quả núi chắn trước nhà; ông nói đời mình không xong thì đời con cháu tiếp tục. Đừng bị chữ "Ngu" đánh lừa: đây là tên người, và câu chuyện ca ngợi ý chí bền bỉ.'));
add(AL, 4, '"Châu về Hợp Phố" chỉ điều gì?', ['Vật quý (hoặc người) trở về với chủ cũ, nơi cũ', 'Một chuyến du lịch', 'Người đi buôn ngọc trai', 'Sự chia li mãi mãi'], ex('Tương truyền quan lại ở Hợp Phố tham lam, ngọc trai bỏ đi nơi khác; khi có quan thanh liêm, ngọc lại về. Ngày nay câu này dùng khi của quý, người thân trở lại sau thời gian xa cách.'));
add(AL, 4, '"Gương vỡ lại lành" gợi điều gì?', ['Vợ chồng chia li nay được đoàn tụ', 'Đồ vật được sửa chữa', 'Sự may mắn trong buôn bán', 'Bạn bè cãi nhau'], ex('Điển kể đôi vợ chồng bẻ đôi chiếc gương làm tin khi loạn lạc, về sau nhờ nửa gương mà tìm lại được nhau. Trái nghĩa là "gương vỡ khó lành" (tan vỡ không hàn gắn được).'));
add(AL, 5, 'Điển "bát cơm Phiếu mẫu" (Hàn Tín) thường được dùng để nói về…', ['Ơn nhỏ lúc hoạn nạn được đền đáp xứng đáng', 'Một bữa ăn sang trọng', 'Người mẹ nghiêm khắc', 'Sự keo kiệt'], ex('Lúc nghèo đói, Hàn Tín được một bà giặt lụa (Phiếu mẫu) cho ăn; khi thành danh, ông đền bà nghìn vàng. Trong Truyện Kiều, lúc báo ân, Kiều cũng nhắc tới tích này để nói ơn nhỏ mà nghĩa lớn.'));
add(AL, 3, 'Truyện "Đẽo cày giữa đường" phê phán điều gì?', ['Thiếu chính kiến, ai nói gì cũng nghe theo nên hỏng việc', 'Sự chăm chỉ làm nông', 'Kĩ thuật làm cày', 'Việc đi đường xa'], ex('Anh chàng đẽo cày ở vệ đường, ai góp ý gì cũng đẽo theo, cuối cùng hỏng cả cây gỗ. Bài học: biết lắng nghe nhưng phải có chủ kiến và hiểu rõ việc mình làm.'));
add(AL, 4, 'Câu "Chim Việt đậu cành Nam, ngựa Hồ hí gió Bắc" gợi tình cảm gì?', ['Lòng nhớ quê hương, không quên gốc gác', 'Tình yêu loài vật', 'Ý chí chinh phục phương xa', 'Sự sợ hãi chiến tranh'], ex('Chim đất Việt (phương nam) làm tổ ở cành phía nam; ngựa đất Hồ (phương bắc) hí khi gió bắc thổi. Ngay cả loài vật còn nhớ quê, huống chi con người.'));
add(AL, 3, '"Đẽo chân cho vừa giày" chỉ cách làm như thế nào?', ['Máy móc, gò ép thực tế cho vừa khuôn có sẵn, thay vì điều chỉnh khuôn cho hợp thực tế', 'Đóng giày khéo léo', 'Chăm sóc đôi chân', 'Tiết kiệm tiền mua giày'], ex('Giày chật thì phải đổi giày, đằng này lại đẽo chân. Thành ngữ phê phán lối áp dụng rập khuôn, hi sinh cái gốc (con người, thực tế) cho cái phụ (khuôn mẫu).'));
add(AL, 5, 'Vì sao khi đọc thơ trung đại, việc hiểu điển cố lại quan trọng?', ['Điển cố nén cả một câu chuyện vào vài chữ; không biết tích sẽ hiểu sai hoặc hiểu nông nghĩa câu thơ', 'Vì điển cố là lỗi chính tả cần sửa', 'Vì mọi câu thơ đều có điển cố', 'Vì điển cố chỉ để trang trí'], ex('Ví dụ "sân Lai", "gốc tử": đọc nghĩa đen chỉ thấy cái sân, cái cây, nhưng biết tích thì hiểu được nỗi nhớ cha mẹ. Điển cố là cách nói hàm súc, uyên bác, đặc trưng của văn chương trung đại.'));

// ── Lời dẫn trực tiếp, gián tiếp ─────────────────────────────
const QT = 'lit.quotation';
add(QT, 3, 'Câu sau dùng cách dẫn nào? Nguyễn Du viết: "Trăm năm trong cõi người ta, / Chữ tài chữ mệnh khéo là ghét nhau."', ['Lời dẫn trực tiếp', 'Lời dẫn gián tiếp', 'Không có lời dẫn', 'Lời người kể chuyện'], ex('Dấu hiệu lời dẫn trực tiếp: dấu hai chấm + ngoặc kép + giữ nguyên văn. Khi trích thơ làm dẫn chứng, luôn dẫn trực tiếp để chính xác.'));
add(QT, 3, 'Chuyển sang lời dẫn gián tiếp: Mẹ dặn tôi: "Con nhớ mang áo mưa nhé!"', ['Mẹ dặn tôi nhớ mang áo mưa.', 'Mẹ dặn tôi: con nhớ mang áo mưa nhé!', 'Mẹ dặn tôi rằng: "Con nhớ mang áo mưa nhé!"', 'Mẹ dặn: "Tôi nhớ mang áo mưa."'], ex('Lời dẫn gián tiếp: bỏ dấu hai chấm và ngoặc kép, đổi "con" thành người được nhắc ("tôi"), bỏ các từ cảm thán như "nhé". Phương án có cả "rằng" lẫn ngoặc kép là lỗi trộn hai cách dẫn.'));
add(QT, 4, 'Chuyển sang lời dẫn gián tiếp: Nam nói với tôi: "Tớ sẽ cho cậu mượn cuốn sách này."', ['Nam nói với tôi rằng bạn ấy sẽ cho tôi mượn cuốn sách đó.', 'Nam nói với tôi rằng tớ sẽ cho cậu mượn cuốn sách này.', 'Nam nói với tôi: "Bạn ấy sẽ cho tôi mượn cuốn sách đó."', 'Nam nói rằng: "tớ sẽ cho cậu mượn sách".'], ex('Đổi ngôi theo góc nhìn của người thuật: "tớ" (Nam) → "bạn ấy"; "cậu" (tôi) → "tôi". Từ chỉ định "này" (gần người nói) có thể đổi thành "đó". Giữ nguyên "tớ", "cậu" là lỗi hay gặp nhất.'));
add(QT, 4, 'Chuyển sang lời dẫn trực tiếp: Thầy khuyên chúng tôi nên đọc sách mỗi ngày.', ['Thầy khuyên chúng tôi: "Các em nên đọc sách mỗi ngày."', 'Thầy khuyên chúng tôi: chúng tôi nên đọc sách mỗi ngày.', 'Thầy khuyên chúng tôi rằng "chúng tôi nên đọc sách".', 'Thầy khuyên: "Thầy nên đọc sách mỗi ngày."'], ex('Khi chuyển sang trực tiếp, phải khôi phục lời nói như lúc thầy nói ra: thầy gọi học sinh là "các em". Thêm dấu hai chấm và ngoặc kép, viết hoa chữ đầu lời dẫn.'));
add(QT, 3, 'Chuyển sang lời dẫn gián tiếp: Cô hỏi tôi: "Em đã làm bài tập chưa?"', ['Cô hỏi tôi đã làm bài tập chưa.', 'Cô hỏi tôi: em đã làm bài tập chưa?', 'Cô hỏi tôi rằng: "Em đã làm bài tập chưa?"', 'Cô hỏi tôi đã làm bài tập chưa?"'], ex('Khi dẫn gián tiếp một câu hỏi, câu tổng thể trở thành câu trần thuật nên kết thúc bằng dấu chấm, không dùng dấu chấm hỏi. "Em" (lời cô gọi tôi) đổi thành người được nhắc tới.'));
add(QT, 4, 'Dấu hiệu nào giúp nhận biết lời dẫn gián tiếp?', ['Thuật lại ý, không có ngoặc kép, có thể thêm "rằng" hoặc "là" trước lời dẫn', 'Luôn có dấu hai chấm và ngoặc kép', 'Luôn có dấu gạch ngang đầu dòng', 'Phải giữ nguyên từng chữ của người nói'], ex('Trực tiếp = nguyên văn + hai chấm + ngoặc kép. Gián tiếp = thuật lại có điều chỉnh, không ngoặc kép; "rằng/là" có thể có hoặc không. Gạch ngang đầu dòng là dấu hiệu của lời thoại nhân vật trong truyện.'));
add(QT, 5, 'Câu nào mắc lỗi khi dẫn lời?', ['Bác Hồ dạy rằng: "các cháu phải chăm học".', 'Bác Hồ dạy rằng thiếu nhi phải chăm học.', 'Bác Hồ dạy thiếu nhi phải chăm học.', 'Ông bà ta thường khuyên con cháu phải chăm học.'], ex('Phương án đầu trộn hai cách dẫn: có "rằng" của gián tiếp nhưng lại có hai chấm, ngoặc kép của trực tiếp. Hơn nữa, lời trong ngoặc kép phải là nguyên văn có thật; nếu không chắc nguyên văn thì hãy dẫn gián tiếp.'));
add(QT, 4, 'Trong bài nghị luận văn học, khi trích dẫn thơ, cần lưu ý điều gì?', ['Chép chính xác từng chữ, đặt trong ngoặc kép (hoặc tách dòng), trích vừa đủ và luôn kèm phân tích', 'Có thể sửa vài chữ cho hay hơn', 'Trích càng dài càng tốt', 'Không cần ngoặc kép vì người chấm đã biết bài thơ'], ex('Sai một chữ khi trích thơ là mất điểm, vì nó cho thấy người viết không nắm văn bản. Trích dài mà không phân tích cũng không được điểm; trích dẫn chỉ là "nguyên liệu" cho phần bình.'));
add(QT, 5, 'Em nhớ ý một nhận định của nhà phê bình nhưng không nhớ nguyên văn. Nên dẫn thế nào?', ['Dẫn gián tiếp: thuật lại ý và nêu rõ đó là ý kiến của ai', 'Đặt vào ngoặc kép như nguyên văn', 'Tự nhận là ý kiến của mình', 'Bịa ra một câu nghe hay hơn'], ex('Ngoặc kép là lời cam kết "đây là nguyên văn". Nếu không chắc, hãy dẫn gián tiếp ("Có ý kiến cho rằng…", "Nhà phê bình X từng nhận xét rằng…"). Đây là sự trung thực khi viết.'));
add(QT, 4, 'Trong câu: Minh tự nhủ: "Ngày mai mình nhất định phải xin lỗi bố." — phần trong ngoặc kép là…', ['Lời dẫn trực tiếp ý nghĩ (lời nhân vật tự nói với mình)', 'Lời dẫn gián tiếp', 'Lời người kể chuyện', 'Lời của tác giả'], ex('Lời dẫn không chỉ là lời nói mà còn có thể là ý nghĩ (tự nhủ, nghĩ thầm). Ý nghĩ được giữ nguyên văn, đặt sau dấu hai chấm, trong ngoặc kép thì vẫn là lời dẫn trực tiếp.'));
add(QT, 5, 'Chuyển sang lời dẫn gián tiếp: Ông cha ta dạy: "Uống nước nhớ nguồn."', ['Ông cha ta dạy rằng khi hưởng thành quả phải nhớ ơn những người đã tạo ra nó.', 'Ông cha ta dạy rằng: "Uống nước nhớ nguồn."', 'Ông cha ta dạy: uống nước nhớ nguồn!', 'Ông cha ta dạy "uống nước nhớ nguồn" rằng.'], ex('Lời dẫn gián tiếp cho phép diễn đạt lại theo ý, không cần giữ nguyên chữ. Phương án có cả "rằng:" lẫn ngoặc kép là lỗi trộn cách dẫn. Lưu ý: nếu muốn giữ nguyên câu tục ngữ, hãy dùng lời dẫn trực tiếp.'));
add(QT, 3, 'Trong câu: Cô giáo nói: "Tuần sau lớp mình đi tham quan." — lời dẫn được tách khỏi lời người dẫn bằng…', ['Dấu hai chấm và dấu ngoặc kép', 'Dấu phẩy và ngoặc đơn', 'Dấu chấm phẩy', 'Dấu chấm lửng'], ex('Công thức của lời dẫn trực tiếp: lời người dẫn + dấu hai chấm + "lời dẫn viết hoa chữ đầu". Lời dẫn trực tiếp cũng có thể đứng trước, ví dụ: "Tuần sau lớp mình đi tham quan", cô giáo nói.'));
add(QT, 4, 'Sáng thứ Hai, Lan nói: "Hôm nay mình bị ốm." Đến thứ Tư, em thuật lại cho bạn. Cách nào hợp lí nhất?', ['Hôm thứ Hai, Lan nói rằng hôm đó bạn ấy bị ốm.', 'Lan nói rằng hôm nay mình bị ốm.', 'Lan nói: "Hôm đó bạn ấy bị ốm."', 'Lan nói rằng hôm nay bạn ấy bị ốm.'], ex('Khi thuật lại ở một thời điểm khác, phải điều chỉnh từ chỉ thời gian ("hôm nay" → "hôm đó") và đại từ ("mình" → "bạn ấy") để người nghe không hiểu nhầm.'));
add(QT, 4, 'Trong văn nghị luận, dùng lời dẫn trực tiếp (trích nguyên văn ý kiến của người có uy tín) có tác dụng gì?', ['Tăng tính khách quan, xác thực và sức thuyết phục cho lập luận', 'Làm bài dài hơn', 'Thay thế hoàn toàn cho lí lẽ của người viết', 'Giúp tránh phải giải thích'], ex('Lời dẫn là bằng chứng, nhưng sau khi dẫn vẫn phải giải thích, phân tích để nối nó với luận điểm. Chỉ dẫn mà không bàn thì chưa phải là lập luận.'));
add(QT, 5, 'Câu nào là lời dẫn gián tiếp đúng?', ['Nhiều người cho rằng đọc sách là cách tự học hiệu quả nhất.', 'Nhiều người cho rằng: "Đọc sách là cách tự học hiệu quả nhất".', 'Nhiều người cho rằng "đọc sách" rằng là cách tự học.', 'Nhiều người cho: đọc sách là cách tự học hiệu quả nhất rằng.'], ex('Gián tiếp: không hai chấm, không ngoặc kép, lời dẫn hoà vào câu như một thành phần. Phương án thứ hai là lỗi kinh điển "rằng: …" (rằng đi kèm hai chấm và ngoặc kép).'));
add(QT, 3, 'Lời dẫn trực tiếp và gián tiếp giống nhau ở điểm nào?', ['Đều là cách đưa lời nói hoặc ý nghĩ của người khác (hoặc của chính mình trước đó) vào lời của mình', 'Đều phải giữ nguyên văn', 'Đều phải đặt trong ngoặc kép', 'Đều chỉ dùng trong thơ'], ex('Cả hai đều là "dẫn" lời. Khác nhau ở cách dẫn: trực tiếp thì giữ nguyên văn, đặt trong ngoặc kép; gián tiếp thì thuật lại ý, không có ngoặc kép.'));

// ── Liên kết câu, câu ghép ───────────────────────────────────
const LK = 'lit.linking';
add(LK, 3, '"Trời đã tối nhưng bố vẫn chưa về." Quan hệ giữa hai vế câu ghép là…', ['Tương phản', 'Nguyên nhân – kết quả', 'Điều kiện – kết quả', 'Lựa chọn'], ex('"Nhưng" báo hiệu điều xảy ra trái với mong đợi → quan hệ tương phản. Các cặp từ tương phản hay gặp: tuy… nhưng, mặc dù… nhưng, dù… vẫn.'));
add(LK, 3, '"Hoặc là cậu ở lại trông nhà, hoặc là chúng ta cùng đi." Quan hệ giữa các vế là…', ['Lựa chọn', 'Tăng tiến', 'Tương phản', 'Nguyên nhân'], ex('"Hoặc… hoặc", "hay" đưa ra các khả năng để chọn một → quan hệ lựa chọn.'));
add(LK, 4, '"Trời càng về khuya, sương xuống càng dày." Quan hệ giữa hai vế là…', ['Tăng tiến (tương ứng: vế này tăng thì vế kia tăng theo)', 'Tương phản', 'Lựa chọn', 'Điều kiện – kết quả'], ex('Cặp "càng… càng" diễn tả sự tăng lên song song, thuộc nhóm quan hệ tăng tiến. Đừng nhầm với "nếu… thì" (điều kiện).'));
add(LK, 4, 'Câu nào là câu ghép?', ['Mặt trời lên, sương tan dần.', 'Khi mặt trời lên, chúng tôi bắt đầu lên đường.', 'Những bông hoa mà em trồng đã nở.', 'Lan và Hoa đều học rất giỏi.'], ex('Câu ghép có từ hai cụm chủ – vị trở lên, không cụm nào nằm trong cụm nào: "mặt trời / lên", "sương / tan dần". Câu 2 có trạng ngữ chứa C–V nhưng nòng cốt chỉ có một cụm C–V; câu 3 có C–V làm định ngữ; câu 4 chỉ có chủ ngữ ghép.'));
add(LK, 4, '"Lan đạt giải Nhất cuộc thi hùng biện. Điều đó khiến cả lớp vô cùng tự hào." Cụm "Điều đó" thể hiện phép liên kết…', ['Phép thế (thay cho cả nội dung câu trước)', 'Phép lặp', 'Phép nối', 'Phép trái nghĩa'], ex('Phép thế không chỉ thay cho một từ mà có thể thay cho cả một sự việc ở câu trước ("điều đó", "việc ấy", "như vậy"). Nhờ đó tránh phải nhắc lại cả câu dài.'));
add(LK, 4, '"Người tốt luôn được mọi người yêu mến. Kẻ xấu sớm muộn cũng bị xa lánh." Hai câu liên kết chủ yếu nhờ…', ['Dùng các từ trái nghĩa (tốt – xấu, yêu mến – xa lánh)', 'Phép nối', 'Phép thế', 'Lặp lại chủ ngữ'], ex('Ngoài lặp, thế, nối, các câu còn có thể liên kết nhờ những từ cùng trường nghĩa, đồng nghĩa hoặc trái nghĩa. Ở đây các cặp trái nghĩa tạo sự đối chiếu, gắn hai câu thành một ý.'));
add(LK, 5, '"Nam gặp Minh ở cổng trường. Cậu ấy rất vui." Đoạn văn mắc lỗi gì?', ['Phép thế mơ hồ: "cậu ấy" có thể là Nam hoặc Minh', 'Thiếu phép nối', 'Lặp từ', 'Sai quan hệ nguyên nhân'], ex('Đại từ thay thế phải chỉ rõ một đối tượng. Khi câu trước có hai người cùng loại, "cậu ấy" gây mơ hồ. Sửa: "Minh rất vui khi gặp lại Nam."'));
add(LK, 5, '"Trời nắng như đổ lửa. Vì vậy, chúng tôi mặc thêm áo ấm." Lỗi liên kết là…', ['Lỗi logic: từ nối "vì vậy" đưa ra kết quả không hợp với nguyên nhân', 'Lỗi lặp từ', 'Lỗi thiếu chủ ngữ', 'Lỗi dùng sai dấu câu'], ex('Liên kết không chỉ cần từ nối đúng hình thức mà nội dung phải hợp lí (liên kết logic). Nắng nóng thì không thể "vì vậy mặc áo ấm". Sửa: "…Vì vậy, chúng tôi đội mũ và mang theo nước."'));
add(LK, 3, 'Từ nối nào báo hiệu phần tổng kết?', ['Tóm lại', 'Tuy nhiên', 'Ngoài ra', 'Trái lại'], ex('Tóm lại, nhìn chung, nói tóm lại → tổng kết. Tuy nhiên, trái lại → đối lập; ngoài ra, bên cạnh đó → bổ sung. Chọn đúng từ nối giúp người đọc theo được mạch lập luận.'));
add(LK, 3, 'Điền cặp từ thích hợp: "___ trời rét đậm, ___ các em vẫn đến lớp đầy đủ."', ['Tuy / nhưng', 'Vì / nên', 'Nếu / thì', 'Không những / mà còn'], ex('Rét đậm mà vẫn đi học đầy đủ = trái với điều dễ xảy ra → tương phản (tuy… nhưng). "Vì… nên" sẽ biến câu thành "rét nên đi học đầy đủ", nghe vô lí.'));
add(LK, 5, '"Gió thổi mạnh; sóng biển vỗ ầm ầm vào bờ." Hai vế câu ghép được nối với nhau bằng…', ['Dấu chấm phẩy, không dùng từ nối', 'Quan hệ từ "và"', 'Cặp quan hệ từ', 'Phó từ "cũng"'], ex('Các vế câu ghép có thể nối bằng từ nối (và, nhưng, vì…) hoặc nối trực tiếp bằng dấu phẩy, dấu chấm phẩy, dấu hai chấm. Khi không có từ nối, phải dựa vào nghĩa để biết quan hệ (ở đây là đồng thời, gần với nguyên nhân – kết quả).'));
add(LK, 5, '"Bên cạnh những lợi ích ấy, mạng xã hội cũng có không ít mặt trái." Câu mở đoạn này liên kết với đoạn trước bằng…', ['Phép nối ("bên cạnh") kết hợp phép thế ("những lợi ích ấy")', 'Chỉ phép lặp', 'Phép trái nghĩa', 'Không có liên kết'], ex('"Bên cạnh" là từ ngữ chuyển tiếp (phép nối) báo hiệu ý bổ sung, ngược chiều; "những lợi ích ấy" thay cho cả nội dung đoạn trước (phép thế). Câu chuyển đoạn tốt thường kết hợp nhiều phép liên kết.'));
add(LK, 4, 'Liên kết và mạch lạc khác nhau thế nào?', ['Liên kết là sự nối kết bằng phương tiện ngôn ngữ (từ nối, từ thay thế…); mạch lạc là sự thống nhất, hợp lí về nội dung và trình tự ý', 'Hai khái niệm giống hệt nhau', 'Mạch lạc chỉ có trong thơ', 'Liên kết chỉ có trong truyện'], ex('Một đoạn có thể đủ từ nối mà vẫn không mạch lạc (ý rời rạc, lạc chủ đề). Muốn viết tốt cần cả hai: ý thống nhất, trình tự hợp lí và phương tiện liên kết phù hợp.'));
add(LK, 3, '"Em yêu Hà Nội. Hà Nội có những con phố nhỏ rợp bóng cây." Hai câu liên kết bằng phép…', ['Lặp từ ngữ', 'Thế', 'Nối', 'Trái nghĩa'], ex('Từ "Hà Nội" ở câu trước được nhắc lại ở câu sau → phép lặp. Nếu câu sau viết "Thành phố ấy…" thì là phép thế.'));
add(LK, 4, 'Gộp hai câu thành câu ghép chỉ điều kiện – kết quả: "Em chăm luyện viết. Chữ em sẽ đẹp hơn."', ['Nếu em chăm luyện viết thì chữ em sẽ đẹp hơn.', 'Tuy em chăm luyện viết nhưng chữ em sẽ đẹp hơn.', 'Em chăm luyện viết hay chữ em sẽ đẹp hơn.', 'Càng em chăm luyện viết, chữ em sẽ đẹp hơn.'], ex('Quan hệ điều kiện – kết quả dùng "nếu… thì", "hễ… thì", "giá… thì". "Tuy… nhưng" chỉ tương phản; "càng… càng" phải đặt "càng" trước vị ngữ ở cả hai vế ("em càng chăm…, chữ càng đẹp").'));
add(LK, 5, 'Đoạn nào có liên kết chặt chẽ nhất?', ['Nguyễn Du là đại thi hào dân tộc. Ông để lại kiệt tác "Truyện Kiều". Tác phẩm ấy đã được dịch ra nhiều thứ tiếng.', 'Nguyễn Du là đại thi hào. Hà Tĩnh có nhiều đặc sản. Truyện Kiều được dịch ra nhiều thứ tiếng.', 'Nguyễn Du là đại thi hào. Tuy nhiên, ông để lại kiệt tác "Truyện Kiều".', 'Ông để lại kiệt tác. Nguyễn Du là đại thi hào. Nó được dịch nhiều.'], ex('Đoạn đúng dùng phép thế hợp lí ("Ông" thay Nguyễn Du, "Tác phẩm ấy" thay Truyện Kiều) theo trình tự ý tự nhiên. Đoạn 2 lạc chủ đề; đoạn 3 dùng "tuy nhiên" sai quan hệ; đoạn 4 dùng đại từ "ông" trước khi nhắc đến người được thay.'));
add(LK, 4, '"Không chỉ học giỏi, Lan còn rất tích cực trong các hoạt động tình nguyện." Cặp "không chỉ… còn" thể hiện quan hệ…', ['Tăng tiến', 'Tương phản', 'Lựa chọn', 'Nguyên nhân – kết quả'], ex('Ý sau được nâng cao hơn ý trước: học giỏi, hơn thế nữa còn tích cực tình nguyện → tăng tiến. Các cặp cùng loại: không những… mà còn, chẳng những… mà còn.'));

// ── Nghị luận xã hội ─────────────────────────────────────────
const XH = 'lit.nlxh';
add(XH, 3, 'Đề "Suy nghĩ về hiện tượng nghiện điện thoại ở học sinh" thuộc kiểu bài nào?', ['Nghị luận về một hiện tượng đời sống', 'Nghị luận về một tư tưởng, đạo lí', 'Nghị luận văn học', 'Văn thuyết minh'], ex('Hiện tượng đời sống = việc đang xảy ra trong xã hội, có thể quan sát (nghiện điện thoại, bạo lực học đường, xả rác). Tư tưởng, đạo lí = một phẩm chất, quan niệm (lòng biết ơn, sự trung thực). Xác định đúng kiểu bài sẽ chọn đúng dàn ý.'));
add(XH, 4, 'Khi bàn về một hiện tượng tiêu cực, trình tự triển khai hợp lí nhất là…', ['Thực trạng → nguyên nhân → hậu quả → giải pháp → bài học', 'Giải pháp → thực trạng → kết bài', 'Kể chuyện bản thân → kết bài', 'Nguyên nhân → bài học → thực trạng'], ex('Phải thấy hiện tượng (thực trạng) rồi mới hỏi vì sao (nguyên nhân), nó gây ra gì (hậu quả), làm sao khắc phục (giải pháp). Giải pháp nên bám vào nguyên nhân đã nêu.'));
add(XH, 4, 'Giải thích câu tục ngữ "Đi một ngày đàng, học một sàng khôn", ý nào đúng?', ['Đi ra ngoài, trải nghiệm thực tế giúp con người tích luỹ được nhiều hiểu biết', 'Phải đi bộ mỗi ngày cho khoẻ', 'Đi học mỗi ngày được một sàng gạo', 'Ở nhà là tốt nhất'], ex('Khi giải thích, đi từ nghĩa đen ("sàng" là đồ đan để sàng gạo, "một sàng khôn" là rất nhiều điều khôn) sang nghĩa bóng (trải nghiệm làm ta khôn lớn). Dừng ở nghĩa đen là giải thích chưa tới.'));
add(XH, 4, 'Dẫn chứng nào phù hợp nhất cho đoạn văn bàn về lòng dũng cảm, sẵn sàng vì người khác?', ['Năm 2021, anh Nguyễn Ngọc Mạnh ở Hà Nội đã trèo lên mái tôn, đỡ được một bé gái rơi từ tầng cao chung cư.', 'Hà Nội có nhiều chung cư cao tầng.', 'Em rất thích xem phim siêu anh hùng.', 'Một người bạn kể rằng có ai đó đã cứu người.'], ex('Dẫn chứng tốt cần: có thật, cụ thể (ai, khi nào, làm gì), tiêu biểu và đúng luận điểm. Phương án cuối mơ hồ, không kiểm chứng được; hai phương án còn lại không chứng minh lòng dũng cảm.'));
add(XH, 5, 'Phần "bài học nhận thức và hành động" nào tốt nhất cho đề về lòng biết ơn?', ['Biết ơn không chỉ là lời cảm ơn mà là sống tử tế; với em, đó là chăm học, phụ giúp cha mẹ và nhớ ơn thầy cô bằng những việc làm cụ thể.', 'Mọi người cần phải biết ơn.', 'Lòng biết ơn rất quan trọng trong cuộc sống.', 'Ai vô ơn sẽ bị xã hội lên án.'], ex('Bài học tốt có hai tầng: nhận thức (hiểu đúng giá trị) và hành động cụ thể của chính em. Ba phương án còn lại chung chung, hô khẩu hiệu, không gắn với bản thân.'));
add(XH, 5, 'Viết về "sự tự tin", phần phản đề nên đề cập điều gì?', ['Phân biệt tự tin với tự cao, tự phụ; phê phán cả những người tự ti, thiếu niềm tin vào bản thân', 'Khẳng định tự tin luôn có hại', 'Kể lại mở bài', 'Liệt kê các cuộc thi tài năng'], ex('Phản đề làm vấn đề sâu hơn bằng cách chỉ ra biểu hiện lệch lạc (thái quá: tự phụ; bất cập: tự ti). Phản đề không phải là phủ nhận vấn đề.'));
add(XH, 3, 'Câu mở đoạn nào phù hợp cho đề "Ý nghĩa của sự sẻ chia"?', ['Sẻ chia là sợi dây vô hình kết nối con người, làm cho cuộc sống trở nên ấm áp hơn.', 'Hôm qua em đi chợ với mẹ.', 'Có rất nhiều vấn đề trong xã hội.', 'Sẻ chia là gì? Em không biết.'], ex('Câu mở đoạn phải nêu đúng vấn đề và gợi được hướng bàn (ý nghĩa). Mở đoạn bằng chuyện riêng không liên quan hoặc quá chung chung đều khiến người chấm khó thấy vấn đề.'));
add(XH, 4, 'Đề "Bàn về tinh thần trách nhiệm của học sinh". Ý nào lạc đề?', ['Lịch sử hình thành các trường đại học trên thế giới', 'Trách nhiệm với việc học của bản thân', 'Trách nhiệm với gia đình và lớp học', 'Phê phán thói đổ lỗi, ỷ lại'], ex('Mọi ý trong bài phải trả lời câu hỏi của đề. Hãy kiểm tra từng ý bằng cách hỏi: "Ý này có làm rõ tinh thần trách nhiệm của học sinh không?". Lịch sử các trường đại học không làm rõ điều đó.'));
add(XH, 4, 'Thái độ nào cần có khi viết bài nghị luận xã hội?', ['Khách quan, công bằng, nhìn nhận nhiều mặt, tránh khẳng định tuyệt đối', 'Càng gay gắt càng thuyết phục', 'Chỉ nêu cảm xúc cá nhân', 'Luôn phủ nhận ý kiến của người khác'], ex('Những câu như "tất cả giới trẻ đều vô cảm" vừa sai sự thật vừa mất thuyết phục. Dùng các từ chừng mực như "một bộ phận", "không ít", "nhiều". Người chấm đánh giá cao cái nhìn biện chứng.'));
add(XH, 5, 'Giải pháp nào cụ thể và khả thi nhất cho vấn đề "học sinh nghiện mạng xã hội"?', ['Mỗi học sinh tự đặt giới hạn thời gian dùng mạng, tắt thông báo khi học, dành thời gian cho thể thao và đọc sách; gia đình cùng thống nhất "giờ không điện thoại".', 'Cấm hoàn toàn Internet trên toàn quốc.', 'Mọi người cần cố gắng hơn.', 'Chờ các nhà khoa học tìm ra cách.'], ex('Giải pháp tốt: cụ thể, làm được ngay, nêu rõ ai làm (bản thân, gia đình, nhà trường). Giải pháp cực đoan (cấm toàn quốc) hoặc chung chung ("cố gắng hơn") đều bị đánh giá thấp.'));
add(XH, 3, 'Cấu trúc thường dùng của một đoạn văn nghị luận xã hội khoảng 200 chữ là…', ['Câu nêu vấn đề → giải thích → bàn luận (vì sao, biểu hiện, dẫn chứng, phản đề) → bài học → câu kết', 'Kể chuyện → tả cảnh → kết', 'Tiểu sử tác giả → phân tích thơ', 'Chỉ cần ba câu cảm xúc'], ex('Đây là "khung xương" của đoạn văn nghị luận xã hội trong đề thi vào 10. Giới hạn 200 chữ nên mỗi phần chỉ 1–3 câu; phần bàn luận là phần chính.'));
add(XH, 4, 'Dẫn chứng về nghị lực sống nào phù hợp?', ['Nick Vujicic sinh ra không có tay chân nhưng đã trở thành diễn giả truyền cảm hứng đi khắp thế giới.', 'Nick Vujicic là người Úc.', 'Có nhiều diễn giả nổi tiếng.', 'Diễn thuyết là một nghề.'], ex('Dẫn chứng phải thể hiện được phẩm chất cần chứng minh: hoàn cảnh khó khăn + nỗ lực vượt qua + thành quả. Các phương án còn lại đúng sự thật nhưng không nói gì về nghị lực.'));
add(XH, 5, 'Đề: "Có ý kiến cho rằng: Thất bại là mẹ thành công." Ở bước giải thích, ý nào đúng?', ['Thất bại cho ta bài học, kinh nghiệm; biết rút kinh nghiệm thì thất bại trở thành nền tảng dẫn tới thành công', 'Thất bại luôn tốt hơn thành công', 'Muốn thành công phải cố tình thất bại', 'Người mẹ luôn thành công'], ex('Hình ảnh "mẹ" là ẩn dụ: thất bại "sinh ra" thành công. Khi giải thích cũng cần nói rõ điều kiện: chỉ khi biết rút kinh nghiệm. Thiếu điều kiện này dễ dẫn tới hiểu sai kiểu "cứ thất bại là sẽ thành công".'));
add(XH, 4, 'Lỗi nào thường làm giảm giá trị dẫn chứng trong bài nghị luận xã hội?', ['Dẫn chứng bịa đặt, không rõ nguồn hoặc kể quá dài mà không phân tích', 'Dẫn chứng ngắn gọn, có thật', 'Dẫn chứng gắn với luận điểm', 'Dẫn chứng gần gũi với học sinh'], ex('Dẫn chứng cần "đúng – trúng – gọn": đúng sự thật, trúng luận điểm, kể gọn rồi phân tích. Kể dài một câu chuyện mà không rút ra ý nghĩa là biến bài nghị luận thành bài kể chuyện.'));
add(XH, 3, 'Câu tục ngữ nào phù hợp nhất để dẫn dắt bài viết về lòng biết ơn?', ['Uống nước nhớ nguồn.', 'Có công mài sắt có ngày nên kim.', 'Gần mực thì đen, gần đèn thì rạng.', 'Một cây làm chẳng nên non.'], ex('"Uống nước nhớ nguồn" = hưởng thành quả phải nhớ người tạo ra nó → đúng chủ đề biết ơn. Ba câu còn lại nói về kiên trì, môi trường sống và đoàn kết.'));
add(XH, 5, 'Câu kết đoạn nào hay nhất cho đoạn văn về sự kiên trì?', ['Mỗi bước chân nhỏ hôm nay, nếu không dừng lại, sẽ đưa ta tới những đỉnh núi mà ta từng nghĩ là không thể chạm tới.', 'Vậy là em đã viết xong đoạn văn.', 'Kiên trì là kiên trì.', 'Có nhiều vấn đề khác cũng quan trọng.'], ex('Câu kết hay khẳng định lại vấn đề bằng hình ảnh hoặc cách nói giàu sức gợi, để lại dư âm. Câu "Kiên trì là kiên trì" lặp vô nghĩa; câu "Vậy là em đã viết xong" không phải văn nghị luận.'));
add(XH, 4, 'Đề "Suy nghĩ về lối sống vô cảm". Bước giải thích cần làm rõ điều gì?', ['Vô cảm là thờ ơ, dửng dưng trước niềm vui, nỗi đau của người khác và những gì diễn ra xung quanh', 'Vô cảm là khi bị ốm, mất cảm giác', 'Kể tên những người vô cảm', 'Nêu ngay giải pháp'], ex('Bước giải thích trả lời câu hỏi "là gì?", hiểu theo nghĩa xã hội chứ không theo nghĩa y học. Kể tên người cụ thể là việc của phần dẫn chứng; giải pháp nằm ở cuối bài.'));

// ── Nghị luận văn học ────────────────────────────────────────
const VH = 'lit.nlvh';
add(VH, 3, 'Câu chủ đề nào phù hợp nhất cho đoạn văn phân tích bài "Bánh trôi nước"?', ['Qua hình ảnh chiếc bánh trôi, Hồ Xuân Hương vừa cảm thương thân phận chìm nổi, vừa khẳng định vẻ đẹp và phẩm chất son sắt của người phụ nữ.', 'Hồ Xuân Hương là một nhà thơ nữ.', 'Bánh trôi nước là món ăn ngày Tết Hàn thực.', 'Bài thơ có bốn câu.'], ex('Câu chủ đề của đoạn nghị luận văn học cần có: tác giả, tác phẩm, và nhận xét khái quát về nội dung (hoặc nghệ thuật). Các phương án còn lại chỉ là thông tin rời rạc, chưa nêu được vấn đề.'));
add(VH, 4, 'Câu nào là câu PHÂN TÍCH (không phải diễn xuôi) về câu "Thân em vừa trắng lại vừa tròn"?', ['Cặp từ "vừa… lại vừa" như liệt kê, khoe vẻ đẹp trọn vẹn: chiếc bánh trắng tròn, cũng là người phụ nữ có làn da trắng, thân hình đầy đặn.', 'Câu thơ nói thân em trắng và tròn.', 'Câu thơ có bảy chữ.', 'Bánh trôi được làm từ bột nếp.'], ex('Phân tích = chỉ ra từ ngữ, nghệ thuật + nêu tác dụng, ý nghĩa. Câu 2 chỉ là diễn xuôi lại lời thơ, câu 3 và 4 là thông tin bên ngoài, không phải phân tích.'));
add(VH, 4, '"Bảy nổi ba chìm với nước non" — nhận xét nào về nghệ thuật là chính xác?', ['Nhà thơ vận dụng sáng tạo thành ngữ dân gian "ba chìm bảy nổi" để nói thân phận long đong của người phụ nữ', 'Câu thơ dùng phép so sánh có từ "như"', 'Câu thơ dùng nói giảm nói tránh', 'Câu thơ không có giá trị nghệ thuật'], ex('Hồ Xuân Hương thường đưa thành ngữ, tục ngữ vào thơ và biến đổi chúng (đảo "ba chìm bảy nổi" thành "bảy nổi ba chìm"). Câu thơ không có từ "như" nên không phải phép so sánh.'));
add(VH, 4, 'Khi trích dẫn thơ trong đoạn nghị luận văn học, cách làm nào tốt nhất?', ['Trích từng câu, cụm từ then chốt và đan xen với phân tích', 'Chép cả bài thơ rồi mới phân tích', 'Không trích dẫn gì', 'Chỉ trích ở câu kết'], ex('Trích vừa đủ, đúng chỗ: dẫn đến đâu, phân tích đến đó. Chép cả bài tốn thời gian mà không có điểm; không trích dẫn thì phân tích thiếu căn cứ.'));
add(VH, 5, 'Câu văn nào phân tích hay nhất hai câu "Lom khom dưới núi, tiều vài chú, / Lác đác bên sông, chợ mấy nhà"?', ['Phép đảo ngữ đưa hai từ láy "lom khom", "lác đác" lên đầu câu, cùng các từ chỉ số lượng ít ỏi "vài", "mấy", khiến sự sống con người hiện lên nhỏ bé, thưa thớt giữa núi đèo hoang vắng.', 'Hai câu thơ tả tiều phu và chợ.', 'Dưới núi có tiều phu, bên sông có chợ.', 'Hai câu thơ rất hay và em rất thích.'], ex('Một câu phân tích tốt có đủ: chỉ ra nghệ thuật (đảo ngữ, từ láy, từ chỉ số lượng) → tác dụng (nhỏ bé, thưa thớt) → ý nghĩa (cảnh hoang vắng). Câu cuối chỉ là cảm xúc chung chung, không có căn cứ.'));
add(VH, 3, 'Câu nào là nhận xét về NGHỆ THUẬT?', ['Bằng phép đối chỉnh, hai câu thơ tạo nên bức tranh cân xứng, hài hoà.', 'Bài thơ thể hiện nỗi nhớ nhà.', 'Bài thơ được sáng tác khi tác giả đi qua Đèo Ngang.', 'Bài thơ nói về cảnh chiều tà.'], ex('Nghệ thuật = cách viết (thể thơ, biện pháp tu từ, từ ngữ, hình ảnh, nhịp điệu). Nội dung = viết về cái gì, bộc lộ tình cảm gì. Hoàn cảnh sáng tác là thông tin ngoài văn bản.'));
add(VH, 4, 'Phân tích nhân vật trong truyện, cần dựa vào những phương diện nào?', ['Ngoại hình, lời nói, hành động, suy nghĩ và mối quan hệ với các nhân vật khác', 'Chỉ cần tên nhân vật', 'Chỉ cần tóm tắt truyện', 'Cảm xúc của người đọc là đủ'], ex('Nhân vật được khắc hoạ qua nhiều phương diện; phân tích tốt là chọn những chi tiết tiêu biểu ở các phương diện ấy rồi rút ra phẩm chất, ý nghĩa.'));
add(VH, 5, 'Phân tích nhân vật Vũ Nương, chi tiết nào thể hiện rõ nhất tấm lòng của nàng với chồng con?', ['Chồng đi lính, nàng chỉ bóng mình trên vách, bảo con đó là cha, để con không thiếu vắng hình bóng người cha', 'Nàng có tư dung tốt đẹp', 'Nàng sống ở Nam Xương', 'Nàng gặp Phan Lang ở thuỷ cung'], ex('Chi tiết tiêu biểu là chi tiết vừa bộc lộ phẩm chất vừa có vai trò trong cốt truyện. Trò đùa "cái bóng" xuất phát từ tình thương con, nhớ chồng, nhưng cũng chính nó gây ra bi kịch, nên rất đáng phân tích.'));
add(VH, 4, 'Muốn liên hệ mở rộng khi phân tích "Bánh trôi nước", câu ca dao nào phù hợp nhất?', ['"Thân em như tấm lụa đào, / Phất phơ giữa chợ biết vào tay ai."', '"Công cha như núi Thái Sơn…"', '"Bầu ơi thương lấy bí cùng…"', '"Cày đồng đang buổi ban trưa…"'], ex('Liên hệ phải cùng chủ đề hoặc cùng mô típ. "Thân em…" là mô típ than thân của người phụ nữ trong ca dao, gần với lời xưng "Thân em" của Hồ Xuân Hương. Điểm khác là bài thơ còn có lời khẳng định "tấm lòng son" đầy bản lĩnh.'));
add(VH, 5, 'Khi so sánh hai tác phẩm, bước nào thể hiện tư duy cao nhất?', ['Lí giải nguyên nhân của sự giống và khác (hoàn cảnh, thời đại, phong cách tác giả)', 'Liệt kê điểm giống nhau', 'Liệt kê điểm khác nhau', 'Tóm tắt từng tác phẩm'], ex('Chỉ ra giống/khác mới là bước đầu. Bài đạt điểm cao phải giải thích được vì sao có sự khác biệt, ví dụ: hai chữ "ta với ta" khác nhau do tâm trạng và hoàn cảnh của hai nhà thơ.'));
add(VH, 3, 'Thao tác chính khi viết bài nghị luận về một đoạn thơ là…', ['Phân tích kết hợp đánh giá', 'Kể chuyện', 'Miêu tả', 'Thuyết minh quy trình'], ex('Nghị luận văn học = phân tích (chỉ ra cái hay) + đánh giá (khẳng định giá trị). Kể chuyện, miêu tả chỉ dùng xen kẽ rất ít, không được thay cho phân tích.'));
